122	    /** Add a claim as above, carrying the tags typed comma separated (blank: none); see
123	     *  {@link #tagsOf}. */
124	    @Transactional
125	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
126	            String corrects, String ref, String tags) {
127	        Person person = person(sheetId, personId);
128	        corrects = numberOf(corrects);
129	        LocalDate on = date != null ? date : settings.defaultClaimDate(sheetId);
130	        int terms = termsFor(sheetId, person, sheets.today(sheetId));
131	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
132	        refuseClosed(sheetId, dueBy);
133	        refuseRetired(person, on);
134	        refuseBadCorrection(sheetId, personId, amount, corrects, null);
135	        ref = refOf(ref);
136	        refuseRefInUse(sheetId, ref, null);
137	        Claim claim = new Claim(sheetId, personId, scaled(amount), on, dueBy, terms, noteOf(note), corrects);
138	        claim.setRef(ref);
139	        claim.setTags(tagsOf(tags));
140	        boolean late = periods.softClosedOn(sheetId, dueBy);
141	        if (late) {
142	            claim.markLateEntry();
143	        }
144	        Claim added = claims.saveAndFlush(claim);
145	        useTags(sheetId, added);
146	        log(sheetId, user, person, added);
147	        audit.recordOnCommit(line("CLAIM_ADDED", sheetId, user, person, added, added.getNumber())
148	                + (added.getRef() != null ? " ref=" + added.getRef() : "")
149	                + (!added.getTags().isEmpty() ? " tags=" + String.join(",", added.getTags()) : ""));
150	        if (late) {
151	            record("LATE_ENTRY", sheetId, user, person, added);
152	        }
153	        return added;
154	    }
