212	    /** Change a DRAFT claim's amount as the claim form would, keeping its date, note, correction,
213	     *  reference and tags, writing CLAIM_EDITED. A claim in any other status, or one the form would
214	     *  refuse, is passed over and keeps its amount: null then. */
215	    @Transactional
216	    public Claim updateAmount(String sheetId, String user, Long id, BigDecimal amount) {
217	        Optional<Claim> found = claims.findById(id).filter(c -> c.getSheetId().equals(sheetId));
218	        if (found.isEmpty() || found.get().getStatus() != ClaimStatus.DRAFT) {
219	            return null;
220	        }
221	        Claim claim = found.get();
222	        try {
223	            return update(sheetId, user, claim.getPersonId(), id, amount, claim.getDate(), claim.getNote(),
224	                    claim.getCorrects(), claim.getRef(), String.join(",", claim.getTags()));
225	        } catch (ClaimNotEditableException | ClaimLockedException | PeriodClosedException
226	                | PersonRetiredException | CorrectionRefusedException | RefInUseException
227	                | LinedAmountException e) {
228	            return null;
229	        }
230	    }
