232	    /** Add a line to a DRAFT claim, counting as an edit of it: its amount becomes the quantities times
233	     *  the unit amounts of its lines added up, and CLAIM_LINE_ADDED is written ending with the line. A
234	     *  claim that is not a DRAFT, a correction, one due by a day in a closed period, one another user's
235	     *  editor locks, a blank label, a quantity below 1 or a negative unit amount, is refused. */
236	    @Transactional
237	    public Claim addLine(String sheetId, String user, Long personId, Long id, String label, int qty,
238	            BigDecimal unit) {
239	        Person person = person(sheetId, personId);
240	        sheets.lock(sheetId);
241	        Claim claim = claim(sheetId, personId, id);
242	        if (claim.getStatus() != ClaimStatus.DRAFT) {
243	            throw new ClaimNotEditableException(claim.getStatus());
244	        }
245	        refuseClosed(sheetId, claim.getDueBy());
246	        if (claim.lockedAgainst(user)) {
247	            throw new ClaimLockedException(claim.getLockedBy());
248	        }
249	        if (claim.isCorrection()) {
250	            throw new LinedAmountException("A correction takes no lines");
251	        }
252	        String trimmed = label == null ? "" : label.trim();
253	        if (trimmed.isEmpty() || qty < 1 || unit.signum() < 0) {
254	            throw new LinedAmountException("A line needs a label, a quantity of at least 1 and a unit amount");
255	        }
256	        ClaimLine added = lines.save(new ClaimLine(claim.getId(), trimmed, qty, scaled(unit)));
257	        claim.setAmount(lines.findByClaimIdOrderByIdAsc(claim.getId()).stream().map(ClaimLine::total)
258	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2, RoundingMode.UNNECESSARY));
259	        claim.setEditedBy(user);
260	        Claim saved = claims.saveAndFlush(claim);
261	        audit.recordOnCommit(line("CLAIM_LINE_ADDED", sheetId, user, person, saved, saved.getNumber())
262	                + " label=" + added.getLabel() + " qty=" + added.getQty() + " unit=" + added.getUnit().toPlainString());
263	        return saved;
264	    }
