284	    /** Open a claim's editor: lock the claim to the user until they save or cancel it, or the
285	     *  sheet's today changes. A claim that is not a DRAFT, is dated in a closed period, or is locked
286	     *  by another user's editor is refused and takes no lock. */
287	    @Transactional
288	    public Claim lock(String sheetId, String user, Long personId, Long id) {
289	        person(sheetId, personId);
290	        // Lock the sheet first, so two users opening the editor at the same moment take turns.
291	        sheets.lock(sheetId);
292	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
293	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
294	        if (claim.getStatus() != ClaimStatus.DRAFT) {
295	            throw new ClaimNotEditableException(claim.getStatus());
296	        }
297	        refuseClosed(sheetId, claim.getDueBy());
298	        if (claim.lockedAgainst(user)) {
299	            throw new ClaimLockedException(claim.getLockedBy());
300	        }
301	        claim.setLockedBy(user);
302	        return claims.saveAndFlush(claim);
303	    }
