305	    /** Cancel a claim's editor: release the user's lock on it; a lock another user holds is kept. */
306	    @Transactional
307	    public Claim unlock(String sheetId, String user, Long personId, Long id) {
308	        person(sheetId, personId);
309	        sheets.lock(sheetId);
310	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
311	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
312	        if (user.equals(claim.getLockedBy())) {
313	            claim.setLockedBy(null);
314	            claim = claims.saveAndFlush(claim);
315	        }
316	        return claim;
317	    }
