380	    private Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to,
381	            String voidReason, boolean judgedOnOriginal) {
382	        return changeStatus(sheetId, user, personId, id, to, voidReason, judgedOnOriginal, null);
