385	    private Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to,
386	            String voidReason, boolean judgedOnOriginal, LocalDate settledOn) {
387	        Person person = person(sheetId, personId);
388	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
389	        // read below is its latest state.
390	        if (to == ClaimStatus.OPEN || to == ClaimStatus.SETTLED) {
391	            sheets.lock(sheetId);
392	        }
393	        Claim claim = claim(sheetId, personId, id);
394	        settings.refuseUnless(sheetId, user, switch (to) {
395	            case OPEN -> Permission.OPEN;
396	            case SETTLED -> Permission.SETTLE;
397	            case VOID -> Permission.VOID;
398	            case DRAFT, PENDING, DELETED, REVIEW -> throw new StatusChangeRefusedException(claim.getStatus(), to);
399	        });
400	        // While the person's flag is in force only a steward opens their claims.
401	        if (to == ClaimStatus.OPEN && person.flaggedOn(sheets.today(sheetId))
402	                && settings.roleOf(sheetId, user) != Role.STEWARD) {
403	            throw new PermissionRefusedException(user, Permission.OPEN);
404	        }
405	        refuseClosed(sheetId, claim.getDueBy());
406	        // A SETTLED claim is voided only by a steward, within the void window of its settlement.
407	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
408	        if (reversing) {
409	            refuseLateOrUnstewardedVoid(sheetId, user, claim);
410	        } else if (!claim.getStatus().canMoveTo(to)) {
411	            throw new StatusChangeRefusedException(claim.getStatus(), to);
412	        }
413	        String reason = voidReason == null || voidReason.isBlank() ? null : voidReason.trim();
414	        if (to == ClaimStatus.VOID) {
415	            refuseUnreasonedVoid(sheetId, reason);
416	        }
417	        if (to == ClaimStatus.SETTLED && !judgedOnOriginal && claim.openedOrEditedBy(user)) {
418	            throw new OwnClaimSettleRefusedException(user);
419	        }
420	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
421	            throw new StatusChangeRefusedException(claim.getStatus(), to);
422	        }
423	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
424	        // gathered by then.
425	        BigDecimal due = to == ClaimStatus.SETTLED ? settleDueOf(sheetId, person, claim, settledOn) : null;
426	        if (to == ClaimStatus.SETTLED && !judgedOnOriginal) {
427	            refuseUnproved(sheetId, person, claim, due);
428	        }
429	        if (to == ClaimStatus.OPEN) {
430	            refuseUnnoted(sheetId, person, claim);
431	            refuseOverCap(sheetId, claim);
432	            refuseOverMaxOpen(sheetId, claim);
433	        }
434	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, person, claim, user, due)) {
435	            to = ClaimStatus.PENDING;
436	        }
437	        if (to == ClaimStatus.OPEN && overReviewThreshold(sheetId, person, claim)) {
438	            to = ClaimStatus.REVIEW;
439	        }
440	        claim.setStatus(to);
441	        if (to == ClaimStatus.SETTLED || to == ClaimStatus.PENDING) {
442	            // Settled one at a time until a bulk settle marks it with its batch.
443	            claim.setBatch(null);
444	        }
445	        if (to == ClaimStatus.OPEN || to == ClaimStatus.REVIEW) {
446	            // Numbered only once it is settled.
447	            claim.setOpenedBy(user);
448	        } else if (to == ClaimStatus.SETTLED) {
449	            claim.setSettledDue(due);
450	            numberOnSettle(sheetId, claim);
451	        } else if (to == ClaimStatus.VOID) {
452	            claim.setVoidReason(reason);
453	        }
454	        Claim saved = claims.saveAndFlush(claim);
455	        log(sheetId, user, person, saved);
456	        String event = switch (to) {
457	            case OPEN -> "CLAIM_OPENED";
458	            case PENDING -> "CLAIM_PENDING";
459	            case REVIEW -> "CLAIM_REVIEW";
460	            case SETTLED -> "CLAIM_SETTLED";
461	            case VOID -> "CLAIM_VOIDED";
462	            case DRAFT, DELETED -> throw new IllegalStateException("A claim is deleted or restored on its own");
463	        };
464	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
465	        if (to == ClaimStatus.SETTLED) {
466	            line += " due=" + settledDueText(saved);
467	            if (settledOn != null) {
468	                line += " on=" + settledOn;
469	            }
470	        } else if (reversing) {
471	            line += " reversed=" + settledDueText(saved);
472	        }
473	        if (to == ClaimStatus.VOID && reason != null) {
474	            line += " reason=" + reason;
475	        }
476	        audit.recordOnCommit(line);
477	        if (to == ClaimStatus.SETTLED) {
478	            notifyWatchers(sheetId, user, person, saved);
479	        }
480	        return saved;
481	    }
