483	    /** The due a claim is settled at: as it stands now, or (a date given) as it stood at the end of
484	     *  that day; a date after the sheet's today, or one the claim had not been added by, is refused. */
485	    private BigDecimal settleDueOf(String sheetId, Person person, Claim claim, LocalDate on) {
486	        if (on == null) {
487	            return dueOf(sheetId, person, claim);
488	        }
489	        if (on.isAfter(sheets.today(sheetId))) {
490	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
491	        }
492	        Claim then = history.claim(claim.getId(), on)
493	                .orElseThrow(() -> new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED));
494	        return dueOf(sheetId, person, then, on);
495	    }
