532	                .filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
533	                .map(ClaimLogEntry::getOn)
534	                .reduce((first, last) -> last)
535	                .orElse(null);
536	        if (!sheets.today(sheetId).equals(deletedOn)) {
