573	    /** Split an amount off an OPEN claim: it keeps the rest of its amount and loses any figure a
574	     *  statement bound it to, and a new OPEN claim of the split-off amount, with the same date and
575	     *  note and no number (one is given at settlement), opened by the user and due by its date plus the terms in force on it,
576	     *  is listed under the person naming the claim it was split from (a late entry when its due-by falls
577	     *  in a soft-closed period). A claim that is not OPEN, one
578	     *  deferred, one dated in a closed period, an amount not above 0.00 and below the claim's, or a
579	     *  user whose role may not open a claim, is refused. */
580	    @Transactional
581	    public Split split(String sheetId, String user, Long personId, Long id, BigDecimal amount) {
582	        Person person = person(sheetId, personId);
583	        Claim claim = claim(sheetId, personId, id);
584	        settings.refuseUnless(sheetId, user, Permission.OPEN);
585	        refuseClosed(sheetId, claim.getDueBy());
586	        if (claim.getStatus() != ClaimStatus.OPEN || claim.deferredOn(sheets.today(sheetId))) {
587	            throw new SplitRefusedException("A " + claim.getStatus() + " claim cannot be split");
588	        }
589	        BigDecimal part = scaled(amount);
590	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
591	            throw new SplitRefusedException("A claim is split by an amount above 0.00 and below its own");
592	        }
593	        claim.setAmount(claim.getAmount().subtract(part));
594	        claim.unbind();
595	        Claim kept = claims.saveAndFlush(claim);
596	        LocalDate on = kept.getDate();
597	        int terms = termsFor(sheetId, person, sheets.today(sheetId));
598	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
599	        Claim split = Claim.splitOff(kept, part, dueBy, terms, null, user);
600	        if (periods.softClosedOn(sheetId, dueBy)) {
601	            split.markLateEntry();
602	        }
603	        Claim added = claims.saveAndFlush(split);
604	        log(sheetId, user, person, added);
605	        audit.recordOnCommit(line("CLAIM_SPLIT", sheetId, user, person, kept, kept.getNumber())
606	                + " into=" + (added.getNumber() != null ? added.getNumber() : ""));
607	        record("CLAIM_OPENED", sheetId, user, person, added);
608	        return new Split(kept, added);
609	    }
