718	    /** Share a claim with another person on the sheet at a share percent (two decimals, more than
719	     *  0.00): CLAIM_SHARED is written ending with the holder and their share. The claim's own person,
720	     *  a person already holding a share, shares totalling more than 100.00, a SETTLED, VOID or DELETED
721	     *  claim, or one dated in a closed period, is refused. */
722	    @Transactional
723	    public Claim share(String sheetId, String user, Long personId, Long id, Long withPersonId, BigDecimal share) {
724	        Person person = person(sheetId, personId);
725	        Claim claim = claim(sheetId, personId, id);
726	        Person holder = person(sheetId, withPersonId);
727	        ClaimStatus status = claim.getStatus();
728	        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID || status == ClaimStatus.DELETED) {
729	            throw new ShareRefusedException("A " + status + " claim cannot be shared");
730	        }
731	        if (periods.closedOn(sheetId, claim.getDate())) {
732	            throw new PeriodClosedException("A claim dated " + claim.getDate() + " falls in a closed period");
733	        }
734	        if (holder.getId().equals(person.getId())) {
735	            throw new ShareRefusedException("A claim cannot be shared with its own person");
736	        }
737	        if (share.signum() <= 0 || share.scale() > 2) {
738	            throw new ShareRefusedException("A share must be more than 0.00, with two decimals");
739	        }
740	        List<ClaimShare> held = claim.getShares();
741	        if (held.stream().anyMatch(s -> s.personId().equals(holder.getId()))) {
742	            throw new ShareRefusedException(holder.getName() + " already holds a share of the claim");
743	        }
744	        BigDecimal total = held.stream().map(ClaimShare::share).reduce(share, BigDecimal::add);
745	        if (total.compareTo(BigDecimal.valueOf(100)) > 0) {
746	            throw new ShareRefusedException("The shares of a claim cannot total more than 100.00");
747	        }
748	        BigDecimal scaledShare = share.setScale(2);
749	        claim.addShare(new ClaimShare(holder.getId(), scaledShare, sheets.today(sheetId)));
750	        Claim saved = claims.saveAndFlush(claim);
751	        audit.recordOnCommit(line("CLAIM_SHARED", sheetId, user, person, saved, saved.getNumber())
752	                + " with=" + holder.getName() + " share=" + scaledShare.toPlainString());
753	        return saved;
754	    }
