756	    /** Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date is the sheet's
757	     *  today. A claim in any other status, or one already reminded on the sheet's today, is refused. When
758	     *  the sheet has an escalation gap and the claim's previous reminder was at least that many days before
759	     *  the sheet's today, ESCALATE is written after REMIND, once per claim ever. */
760	    @Transactional
761	    public Claim remind(String sheetId, String user, Long personId, Long id) {
762	        Person person = person(sheetId, personId);
763	        // Lock the sheet first, so two presses on the same day write one reminder.
764	        sheets.lock(sheetId);
765	        Claim claim = claim(sheetId, personId, id);
766	        LocalDate today = sheets.today(sheetId);
767	        if (!claim.getStatus().isOpen()) {
768	            throw new RemindRefusedException("A " + claim.getStatus() + " claim cannot be reminded");
769	        }
770	        if (today.equals(claim.getRemindedOn())) {
771	            throw new RemindRefusedException("The claim was already reminded on " + today);
772	        }
773	        LocalDate previous = claim.getRemindedOn();
774	        Integer gap = settings.escalateAfter(sheetId);
775	        boolean escalate = gap != null && previous != null && !claim.isEscalated()
776	                && !previous.plusDays(gap).isAfter(today);
777	        claim.setRemindedOn(today);
778	        if (escalate) {
779	            claim.setEscalated(true);
780	        }
781	        Claim saved = claims.saveAndFlush(claim);
782	        record("REMIND", sheetId, user, person, saved);
783	        if (escalate) {
784	            record("ESCALATE", sheetId, user, person, saved);
785	        }
786	        return saved;
787	    }
