935	    /** A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and any figure a
936	     *  statement bound it to stays bound; its period, which follows its due-by, and its number
937	     *  stay too. Anyone but a steward, a claim that is not OPEN or PENDING, a claim whose due-by falls
938	     *  in a closed period, or a new date after its person's retirement, is refused. */
939	    @Transactional
940	    public Claim redate(String sheetId, String user, Long personId, Long id, LocalDate date) {
941	        Person person = person(sheetId, personId);
942	        // Lock the sheet first, as opening does: the claim may take the next number.
943	        sheets.lock(sheetId);
944	        Claim claim = claim(sheetId, personId, id);
945	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
946	            throw new RedateForbiddenException(user);
