88	    /** Move a person up or down the list, swapping them with the person above or below; retired people
89	     *  are passed over unless {@code includeRetired} (the list shows them). Refused when there is no one
90	     *  to swap with: the top person cannot move up nor the bottom one down. */
91	    @Transactional
92	    public Person move(String sheetId, String user, Long id, boolean up, boolean includeRetired) {
93	        Person person = people.findByIdAndSheetId(id, sheetId)
94	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
95	        List<Person> listed = list(sheetId);
96	        List<Person> shown = listed.stream()
97	                .filter(p -> includeRetired || !p.isRetired() || p.getId().equals(id)).toList();
98	        int at = shown.indexOf(person);
99	        int to = up ? at - 1 : at + 1;
100	        if (at < 0 || to < 0 || to >= shown.size()) {
101	            throw new MoveRefusedException(person.getName() + " cannot move " + (up ? "up" : "down"));
102	        }
103	        Person other = shown.get(to);
104	        person.swapPositionWith(other);
105	        people.saveAndFlush(person);
106	        people.saveAndFlush(other);
107	        int position = list(sheetId).indexOf(person) + 1;
108	        audit.recordOnCommit("PERSON_MOVED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
109	                + " position=" + position);
110	        return person;
111	    }
