143	    @Transactional
144	    public Person add(String sheetId, String user, String name, String grade, Integer terms, LocalDate termsFrom,
145	            String contact, String tags) {
146	        LocalDate today = sheets.today(sheetId);
147	        gradeRules.requireChoosable(sheetId, grade);
148	        String trimmed = name.trim();
149	        requireFreeName(sheetId, trimmed, null);
150	        String key = contactKey(contact);
151	        requireFreeContact(sheetId, key, null);
152	        Person person = new Person(sheetId, trimmed, today);
153	        person.setTerms(termsFrom == null ? terms : null);
154	        person.setContact(key);
155	        person.setTags(ClaimService.tagsOf(tags));
156	        Person added = people.saveAndFlush(person);
157	        useTags(sheetId, added);
158	        grades.give(added, grade, null);
159	        if (termsFrom != null) {
160	            this.terms.record(added, terms, termsFrom);
161	        }
162	        Integer inForce = this.terms.termsOn(added, today);
163	        record("PERSON_ADDED", sheetId, user, added, grade, (inForce != null ? " terms=" + inForce : "")
164	                + (key != null ? " contact=" + key : ""));
165	        return added;
