185	    /** Update a person as above, recording their own terms (null for none) from a from-date, keeping
186	     *  those already recorded (those for the same from-date are replaced). Without a from-date the
187	     *  terms are recorded from the beginning of time, unless they are the terms in force on the
188	     *  sheet's today, which are then left as they are. */
189	    @Transactional
190	    public Person update(String sheetId, String user, Long id, long version, String name, String grade,
191	            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, String tags) {
192	        Person person = people.findByIdAndSheetId(id, sheetId)
193	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
194	        if (person.getVersion() != version) {
195	            throw new StalePersonException(person);
196	        }
197	        // A grade left as it is, with no from-date, is not a choice of it: a retired one is kept.
198	        if (gradeFrom != null || !grade.equals(grades.gradeOn(id, sheets.today(sheetId)))) {
199	            gradeRules.requireChoosable(sheetId, grade);
200	        }
201	        String trimmed = name.trim();
202	        requireFreeName(sheetId, trimmed, id);
203	        List<String> tree = sheets.tree(sheetId);
204	        if (!tree.isEmpty()) {
205	            for (PersonAlias alias : aliases.findByPersonIdOrderByIdAsc(id)) {
206	                if (inUseOnTree(tree, alias.getAlias())) {
207	                    throw new NameInUseException(alias.getAlias());
208	                }
209	            }
210	        }
211	        String key = contactKey(contact);
212	        requireFreeContact(sheetId, key, id);
213	        person.setName(trimmed);
214	        LocalDate today = sheets.today(sheetId);
215	        Integer before = this.terms.termsOn(person, today);
216	        boolean termsGiven = termsFrom != null || !Objects.equals(before, terms);
217	        if (termsFrom != null) {
218	            this.terms.record(person, terms, termsFrom);
219	            // Terms recorded change the person, so an editor that loaded them before is stale.
220	            entityManager.lock(person, LockModeType.PESSIMISTIC_FORCE_INCREMENT);
221	        } else if (termsGiven) {
222	            person.setTerms(terms);
223	        }
224	        String contactBefore = person.getContact();
225	        person.setContact(key);
226	        if (tags != null) {
227	            person.setTags(ClaimService.tagsOf(tags));
228	        }
229	        if (gradeFrom != null || !grade.equals(grades.gradeOn(id, today))) {
230	            grades.give(person, grade, gradeFrom != null ? gradeFrom : today);
231	            // A grade given changes the person, so an editor that loaded them before is stale.
232	            entityManager.lock(person, LockModeType.PESSIMISTIC_FORCE_INCREMENT);
233	        }
234	        Person saved = people.saveAndFlush(person);
235	        useTags(sheetId, saved);
236	        record("PERSON_EDITED", sheetId, user, saved, grades.gradeOn(id, today),
237	                (termsGiven ? " terms=" + Objects.requireNonNullElse(this.terms.termsOn(saved, today), "") : "")
238	                + (Objects.equals(contactBefore, key) ? "" : " contact=" + (key != null ? key : "")));
239	        return saved;
240	    }
