547	    /** Refuse a name used, as names are compared, by another person on the sheet (not {@code exceptId}),
548	     *  by an alias on the sheet, or as a name or alias on any other sheet of its tree. */
549	    private void requireFreeName(String sheetId, String name, Long exceptId) {
550	        if (people.nameInUse(sheetId, name, exceptId) || aliases.aliasInUse(sheetId, name)
551	                || inUseOnTree(sheets.tree(sheetId), name)) {
