556	    /** Whether a name or alias on any of the tree's sheets is this name, as names are compared. */
557	    private boolean inUseOnTree(List<String> tree, String name) {
558	        return !tree.isEmpty() && (people.nameInUseOn(tree, name) || aliases.aliasInUseOn(tree, name));
559	    }
560	
561	    /** The names and aliases on the other sheets of the sheet's tree, lower-cased. */
562	    private Set<String> treeKeys(String sheetId) {
563	        List<String> tree = sheets.tree(sheetId);
564	        if (tree.isEmpty()) {
565	            return Set.of();
566	        }
567	        Set<String> keys = new java.util.HashSet<>(people.nameKeysOn(tree));
568	        keys.addAll(aliases.aliasKeysOn(tree));
569	        return keys;
570	    }
571	
572	    private static boolean clashes(Set<String> treeKeys, String name, List<String> theirAliases) {
573	        return treeKeys.contains(name.toLowerCase(Locale.ROOT))
574	                || theirAliases.stream().anyMatch(alias -> treeKeys.contains(alias.toLowerCase(Locale.ROOT)));
575	    }
576	
577	    /** Whether the person clashes: their name or an alias of theirs is used as a name or alias on
578	     *  another sheet of their sheet's tree. */
579	    public boolean clashing(Person person) {
580	        return clashes(treeKeys(person.getSheetId()), person.getName(), aliases(person.getId()));
581	    }
582	
583	    /** The ids of the people on the sheet who clash, as {@link #clashing(Person)} judges, with the
584	     *  names and aliases given them. */
585	    public Set<Long> clashingIds(String sheetId, List<Person> them, Map<Long, List<String>> theirAliases) {
586	        Set<String> keys = treeKeys(sheetId);
587	        if (keys.isEmpty()) {
588	            return Set.of();
589	        }
590	        return them.stream().filter(p -> clashes(keys, p.getName(), theirAliases.getOrDefault(p.getId(), List.of())))
591	                .map(Person::getId).collect(Collectors.toSet());
592	    }
