33	/** The figures a sheet rolls up to: each person's claimed, due-total and overdue-total, and the sheet's totals. A
34	 *  change made through {@link #track} is followed in the audit by a line for each person whose
35	 *  figures it moved, then one for the sheet's totals when they moved, then an alert for each person
36	 *  whose due-total it took above the sheet's alert threshold. */
37	@Service
38	public class RollupService {
39	
40	    /** Written for a due-total that has no rate to work from. */
41	    private static final String NO_RATE = "n/a";
42	
43	    private static final BigDecimal NONE = BigDecimal.ZERO.setScale(2);
44	
45	    /** A person's figures; due is null when it has no rate to work from. */
46	    private record Figures(String name, BigDecimal claimed, BigDecimal due, BigDecimal overdue, BigDecimal settled,
47	            int overdueCount, BigDecimal settledTotal, BigDecimal openTotal, BigDecimal cutTotal) {
48	        boolean sameAs(Figures other) {
49	            return other != null && claimed.compareTo(other.claimed) == 0 && Objects.equals(due, other.due)
50	                    && overdue.compareTo(other.overdue) == 0;
51	        }
52	    }
53	
54	    /** The sheet's figures: each person's, in list order, and the totals. */
55	    private record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
56	            BigDecimal overdueTotal) {
57	    }
58	
59	    private final ClaimRepository claims;
60	    private final ClaimService claimService;
61	    private final RateService rates;
62	    private final PersonGradeService grades;
63	    private final PersonService personService;
64	    private final SheetService sheets;
65	    private final SettingService settings;
66	    private final History history;
67	    private final PoolCutService cuts;
68	    private final Audit audit;
69	
70	    public RollupService(ClaimRepository claims, ClaimService claimService,
71	            RateService rates, PersonGradeService grades, PersonService personService, SheetService sheets,
72	            SettingService settings, History history, PoolCutService cuts, Audit audit) {
73	        this.history = history;
74	        this.cuts = cuts;
75	        this.claims = claims;
76	        this.claimService = claimService;
77	        this.rates = rates;
78	        this.grades = grades;
79	        this.personService = personService;
80	        this.sheets = sheets;
81	        this.settings = settings;
82	        this.audit = audit;
83	    }
84	
85	    /** Make a change to the sheet, then record in the audit the figures it moved. The sheet is held
86	     *  locked throughout, so a change made at the same moment waits and the figures are its own. */
87	    @Transactional
88	    public <T> T track(String sheetId, String user, Supplier<T> change) {
89	        sheets.lock(sheetId);
90	        Rollup before = rollup(sheetId);
91	        T result = change.get();
92	        Rollup after = rollup(sheetId);
93	        after.people().forEach((id, figures) -> {
94	            if (!figures.sameAs(before.people().get(id))) {
95	                audit.recordOnCommit(rollupLine(sheetId, user, figures));
96	            }
97	        });
98	        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
99	                || after.dueTotal().compareTo(before.dueTotal()) != 0
100	                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
101	            audit.recordOnCommit(totalsLine(sheetId, user, after));
102	        }
103	        BigDecimal threshold = settings.alertThreshold(sheetId);
104	        if (threshold != null) {
105	            after.people().forEach((id, figures) -> {
106	                Figures was = before.people().get(id);
107	                if (above(figures.due(), threshold) && (was == null || !above(was.due(), threshold))) {
108	                    audit.recordOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
109	                            + " due-total=" + figures.due().toPlainString());
110	                }
111	            });
112	        }
113	        return result;
114	    }
115	
116	    /** Record in the audit every person's figures as they stand now, in list order, then the sheet's
117	     *  totals: the figures a sheet starts from when it is made whole (a clone). */
118	    @Transactional
119	    public void recordAll(String sheetId, String user) {
120	        Rollup now = rollup(sheetId);
121	        now.people().values().forEach(figures -> audit.recordOnCommit(rollupLine(sheetId, user, figures)));
122	        audit.recordOnCommit(totalsLine(sheetId, user, now));
123	    }
