130	    private static String rollupLine(String sheetId, String user, Figures figures) {
131	        return "ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
132	                + " claimed=" + figures.claimed().toPlainString() + " due-total=" + text(figures.due())
133	                + " overdue-total=" + figures.overdue().toPlainString();
134	    }
