187	    /** The sheet's figures broken down as it stood at the end of a day, that day standing in for the
188	     *  sheet's today (null: as it shows them now). */
189	    @Transactional(readOnly = true)
190	    public Breakdown breakdown(String sheetId, LocalDate asOf) {
191	        LocalDate today = asOf != null ? asOf : sheets.today(sheetId);
192	        Rollup rollup = rollup(sheetId, asOf);
193	        Map<String, BigDecimal> gradeDues = new LinkedHashMap<>();
194	        for (Person person : personService.list(sheetId, asOf)) {
195	            Figures f = rollup.people().get(person.getId());
196	            String grade = grades.gradeOn(person.getId(), today, asOf);
197	            if (person.isRetired() || f == null || grade == null) {
198	                continue;
199	            }
200	            gradeDues.merge(grade, f.due() == null ? NONE : f.due(), BigDecimal::add);
201	        }
202	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDesc(sheetId);
203	        Map<String, Integer> statusCounts = new LinkedHashMap<>();
204	        (asOf == null ? sheetClaims : history.claims(sheetClaims, asOf))
205	                .forEach(claim -> statusCounts.merge(claim.getStatus().name(), 1, Integer::sum));
206	        return new Breakdown(gradeDues, statusCounts);
207	    }
