243	        if (settings.scoreLog(sheetId)) {
244	            rollup.people().values().forEach(figures -> audit.recordOnCommit("SCORE sheet=" + sheetId + " by=" + user
245	                    + " name=" + figures.name() + " score=" + score(figures).toPlainString()));
