254	    /** A person's score: their settled figures (corrections left out) divided by 100, minus 5 for each overdue claim of theirs
255	     *  that counts, rounded half to even to a whole number. */
256	    private static BigDecimal score(Figures figures) {
257	        BigDecimal score = figures.settled().movePointLeft(2).subtract(BigDecimal.valueOf(5L * figures.overdueCount()))
258	                .setScale(0, RoundingMode.HALF_EVEN);
259	        return score.signum() == 0 ? BigDecimal.ZERO : score;
260	    }
