266	    /** The sheet's figures as it stood at the end of a day: its people, claims, holds, grades, rates
267	     *  and settings as they stood then, the day standing in for the sheet's today (null: now). */
268	    private Rollup rollup(String sheetId, LocalDate asOf) {
269	        LocalDate today = asOf != null ? asOf : sheets.today(sheetId);
270	        List<Person> sheetPeople = personService.list(sheetId, asOf);
271	        Map<Long, LocalDate> retiredFrom = new HashMap<>();
272	        sheetPeople.forEach(person -> retiredFrom.put(person.getId(), person.getRetiredFrom()));
273	        Map<Long, List<Claim>> counted = counted(sheetId, asOf, today, retiredFrom);
274	        Map<Long, Shared> shared = sharedParts(sheetId, asOf, sheetPeople, counted);
275	        Map<Long, BigDecimal> cutTotals = cuts.cutTotals(sheetId, asOf, sheetPeople);
276	        Map<Long, Figures> figures = new LinkedHashMap<>();
277	        BigDecimal claimedTotal = NONE;
278	        List<BigDecimal> dues = new ArrayList<>();
279	        List<BigDecimal> overdues = new ArrayList<>();
280	        for (Person person : sheetPeople) {
281	            Figures f = figuresOf(sheetId, today, asOf, person, counted.getOrDefault(person.getId(), List.of()),
282	                    shared.get(person.getId()), cutTotals.getOrDefault(person.getId(), NONE));
283	            figures.put(person.getId(), f);
284	            claimedTotal = claimedTotal.add(f.claimed());
285	            if (f.due() != null) {
286	                dues.add(f.due());
287	            }
288	            overdues.add(f.overdue());
289	        }
290	        return new Rollup(figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
291	    }
