293	    /** The sheet's claims that count, as they stood at the end of a day (null: now), by person id. */
294	    private Map<Long, List<Claim>> counted(String sheetId, LocalDate asOf, LocalDate today,
295	            Map<Long, LocalDate> retiredFrom) {
296	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDesc(sheetId);
297	        return (asOf == null ? sheetClaims : history.claims(sheetClaims, asOf)).stream()
298	                .filter(claim -> claim.countsLive(retiredFrom.get(claim.getPersonId()), today))
299	                .collect(Collectors.groupingBy(Claim::getPersonId));
300	    }
