302	    /** What the shares of the claims that count move in a person's due-total, as it stood at the end of
303	     *  a day (null: now); null when no share moves it. */
304	    public BigDecimal sharedPartOf(String sheetId, Long personId, LocalDate asOf) {
305	        LocalDate today = asOf != null ? asOf : sheets.today(sheetId);
306	        List<Person> sheetPeople = personService.list(sheetId, asOf);
307	        Map<Long, LocalDate> retiredFrom = new HashMap<>();
308	        sheetPeople.forEach(person -> retiredFrom.put(person.getId(), person.getRetiredFrom()));
309	        Shared shared = sharedParts(sheetId, asOf, sheetPeople, counted(sheetId, asOf, today, retiredFrom)).get(personId);
310	        return shared == null ? null : shared.all();
311	    }
312	
313	    /** What the shares of the claims that count move in each person's due-total, by person id: each
314	     *  holder gains their part of the claim (see ClaimService#partOf; a holder whose grade has no rate
315	     *  gains nothing), and the claim's own person loses it. A person whose figures no share moves is
316	     *  not listed; a claim with no figure moves nothing. */
317	    private Map<Long, Shared> sharedParts(String sheetId, LocalDate asOf, List<Person> sheetPeople,
318	            Map<Long, List<Claim>> counted) {
319	        Map<Long, Shared> parts = new HashMap<>();
320	        Set<Long> onSheet = sheetPeople.stream().map(Person::getId).collect(Collectors.toSet());
321	        for (Person person : sheetPeople) {
322	            for (Claim claim : counted.getOrDefault(person.getId(), List.of())) {
323	                if (claim.getShares().isEmpty()) {
324	                    continue;
325	                }
326	                BigDecimal figure = claimService.dueOf(sheetId, person, claim, asOf);
327	                if (figure == null) {
328	                    continue;
329	                }
330	                for (ClaimShare share : claim.getShares()) {
331	                    if (!onSheet.contains(share.personId())) {
332	                        continue;
333	                    }
334	                    BigDecimal part = claimService.partOf(sheetId, claim, share, asOf);
335	                    if (part == null) {
336	                        parts.merge(person.getId(), Shared.of(claim, NONE), Shared::add);
337	                        continue;
338	                    }
339	                    parts.merge(share.personId(), Shared.of(claim, part), Shared::add);
340	                    parts.merge(person.getId(), Shared.of(claim, part.negate()), Shared::add);
341	                }
342	            }
343	        }
344	        return parts;
345	    }
346	
347	    /** What shares move in a person's figures: in all, among SETTLED claims and among OPEN and PENDING ones. */
348	    private record Shared(BigDecimal all, BigDecimal settled, BigDecimal open) {
349	        static Shared of(Claim claim, BigDecimal part) {
350	            return new Shared(part, claim.getStatus() == ClaimStatus.SETTLED ? part : NONE,
351	                    claim.getStatus().isOpen() ? part : NONE);
352	        }
353	
354	        Shared add(Shared other) {
355	            return new Shared(all.add(other.all), settled.add(other.settled), open.add(other.open));
356	        }
357	    }
358	
359	    /** The figures added up, leaving out the single highest and the single lowest when there are
360	     *  three or more. */
361	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
362	        BigDecimal sum = figures.stream().reduce(NONE, BigDecimal::add);
363	        if (figures.size() < 3) {
364	            return sum;
365	        }
366	        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
367	    }
368	
369	    /** A person's figures from their claims that count: the sum of their amounts, leaving out those
370	     *  that correct another claim, and the sum of the
371	     *  figures they show (a held one's included), or none when the grade in force on the sheet's today has no rate in force
372	     *  then and no claim of theirs shows a figure; the sum is held to the cap in force on the date of the latest of them
373	     *  less their cut total. The overdue-total
374	     *  sums the dues of those that are OPEN or PENDING with a due-by plus their grace before the sheet's today.
375	     *  The settled figures, for the score, sum those of SETTLED claims that correct nothing. The
376	     *  due-total takes in what the shares of claims move (null: none moves it): a holder's parts, less
377	     *  the parts others hold of the person's own claims. The settled-total and open-total sum the
378	     *  figures of their SETTLED, and their OPEN and PENDING, claims (corrections included), with what
379	     *  shares of those claims move. */
380	    private Figures figuresOf(String sheetId, LocalDate today, LocalDate asOf, Person person, List<Claim> counted,
381	            Shared shared, BigDecimal cutTotal) {
382	        BigDecimal claimed = NONE;
383	        BigDecimal due = NONE;
384	        BigDecimal overdue = NONE;
385	        BigDecimal settled = NONE;
386	        BigDecimal settledTotal = NONE;
387	        BigDecimal openTotal = NONE;
388	        int overdueCount = 0;
389	        boolean anyFigure = false;
390	        for (Claim claim : counted) {
391	            if (claim.getCorrects() == null) {
392	                claimed = claimed.add(claim.getAmount());
393	            }
394	            BigDecimal figure = claimService.dueOf(sheetId, person, claim, asOf);
395	            boolean late = claim.getStatus().isOpen()
396	                    && claimService.overdueFrom(sheetId, person, claim, asOf).isBefore(today);
397	            if (late) {
398	                overdueCount++;
399	            }
400	            if (figure != null && claim.getStatus() == ClaimStatus.SETTLED && claim.getCorrects() == null) {
401	                settled = settled.add(figure);
402	            }
403	            if (figure != null && claim.getStatus() == ClaimStatus.SETTLED) {
404	                settledTotal = settledTotal.add(figure);
405	            }
406	            if (figure != null && claim.getStatus().isOpen()) {
407	                openTotal = openTotal.add(figure);
408	            }
409	            if (figure != null) {
410	                due = due.add(figure);
411	                if (late) {
412	                    overdue = overdue.add(figure);
413	                }
414	            }
415	            anyFigure |= figure != null;
416	        }
417	        if (shared != null) {
418	            due = due.add(shared.all());
419	            settledTotal = settledTotal.add(shared.settled());
420	            openTotal = openTotal.add(shared.open());
421	            anyFigure = true;
422	        }
423	        boolean hasRate = rates.rateOn(sheetId, grades.gradeOn(person.getId(), today, asOf), today, asOf).isPresent();
424	        LocalDate latest = counted.stream().map(Claim::getDate).max(LocalDate::compareTo).orElse(null);
425	        return new Figures(person.getName(), claimed,
426	                hasRate || anyFigure ? settings.capped(sheetId, due, cutTotal, latest, asOf) : null,
427	                overdue, settled, overdueCount, settledTotal, openTotal, cutTotal);
428	    }
429	
430	    private static String text(BigDecimal due) {
431	        return due == null ? NO_RATE : due.toPlainString();
432	    }
433	}
