25	/** The rates set on a sheet for each grade, each in force from its from-date. A grade with no rate
26	 *  in force on a date on a sheet takes its parent sheet's, then the parent's parent's, up to
27	 *  {@link #PARENT_LEVELS} levels up; with none there either, a sheet that was cloned takes the rate
28	 *  of the sheet it was cloned from, and so on up that sheet's parents and source. */
29	@Service
30	public class RateService {
31	
32	    /** How many levels of parent sheets are looked to for a rate the sheet has none in force for. */
33	    public static final int PARENT_LEVELS = 3;
34	
35	    private final RateRepository rates;
36	    private final RateVersionRepository versions;
37	    private final SheetService sheets;
38	    private final SheetRepository sheetRepository;
