45	    public RateService(RateRepository rates, RateVersionRepository versions, SheetService sheets, SheetRepository sheetRepository, History history,
46	            Audit audit, JdbcTemplate jdbc, GradeService grades, SettingService settings) {
47	        this.settings = settings;
48	        this.jdbc = jdbc;
49	        this.grades = grades;
50	        this.rates = rates;
51	        this.versions = versions;
52	        this.sheets = sheets;
53	        this.sheetRepository = sheetRepository;
54	        this.history = history;
55	        this.audit = audit;
