58	    /** The sheet's parent sheet's id as it stood at the end of a day (null: as it stands now); null
59	     *  when it had none. A sheet whose parent was never kept in its history has it as it stands now. */
60	    private String parentOf(String sheetId, LocalDate asOf) {
61	        if (asOf != null && history.settingsKept(sheetId).contains(SettingService.PARENT)) {
62	            return history.settings(sheetId, asOf).get(SettingService.PARENT);
63	        }
64	        return sheetRepository.findById(sheetId).map(Sheet::getParentId).orElse(null);
65	    }
66	
67	    /** The sheets the sheet's rates fall back to, nearest first: its parent, the parent's parent, up
68	     *  to {@link #PARENT_LEVELS} levels up. */
69	    public List<String> ancestors(String sheetId) {
70	        return ancestors(sheetId, null);
71	    }
72	
73	    /** The sheets the sheet's rates fall back to as they stood at the end of a day (null: now),
74	     *  nearest first: the parent each had then. */
75	    public List<String> ancestors(String sheetId, LocalDate asOf) {
76	        List<String> found = new ArrayList<>();
77	        String sheet = parentOf(sheetId, asOf);
78	        while (sheet != null && found.size() < PARENT_LEVELS && !sheet.equals(sheetId) && !found.contains(sheet)) {
79	            found.add(sheet);
80	            sheet = parentOf(sheet, asOf);
81	        }
82	        return found;
83	    }
84	
85	    /** Every sheet the sheet's rates fall back to, nearest first: its {@link #ancestors} as they stood
86	     *  at the end of a day (null: now); then, for a sheet that was cloned, the sheet it was cloned from
87	     *  and that sheet's own fall-backs as they stand now. A sheet is listed once, the sheet itself never. */
88	    public List<String> fallbacks(String sheetId, LocalDate asOf) {
89	        List<String> found = new ArrayList<>();
90	        Set<String> seen = new HashSet<>(Set.of(sheetId));
91	        String sheet = sheetId;
92	        LocalDate day = asOf;
93	        while (sheet != null) {
94	            for (String ancestor : ancestors(sheet, day)) {
95	                if (seen.add(ancestor)) {
96	                    found.add(ancestor);
97	                }
98	            }
99	            String source = sheetRepository.findById(sheet).map(Sheet::getClonedFrom).orElse(null);
100	            if (source == null || !seen.add(source)) {
101	                break;
102	            }
103	            found.add(source);
104	            sheet = source;
105	            day = null;
106	        }
107	        return found;
108	    }
