110	    /** The sheet's rates by grade, each grade's from the earliest. */
111	    public List<Rate> list(String sheetId) {
112	        return rates.findBySheetIdOrderByGradeAscFromAscIdAsc(sheetId);
113	    }
114	
115	    /** A rate's older versions, newest first: as they were read with it, else from the kept versions. */
116	    public List<Rate> earlier(Rate rate) {
117	        if (rate.getEarlier() != null) {
118	            return rate.getEarlier();
119	        }
120	        List<RateVersion> older = versions.findByRateIdOrderByVersionAsc(rate.getId());
121	        List<Rate> earlier = new ArrayList<>();
122	        for (int i = older.size() - 1; i >= 0; i--) {
123	            RateVersion version = older.get(i);
124	            earlier.add(rate.asVersion(version.getRate(), version.getTo(), version.getVersion(),
125	                    version.getForwardAfter()));
126	        }
127	        rate.setEarlier(earlier);
128	        return earlier;
129	    }
130	
131	    /** The sheet's rates by grade, each grade's from the earliest, as they stood at the end of a day
132	     *  (null: as they stand now). */
133	    public List<Rate> list(String sheetId, LocalDate asOf) {
134	        if (asOf == null) {
135	            return list(sheetId);
136	        }
137	        return grades.grades(sheetId).stream()
138	                .flatMap(grade -> history.rates(sheetId, grade, asOf).stream()
139	                        .sorted(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()))))
140	                .toList();
141	    }
