143	    /** The grade's rate in force on a date: the one whose from-date is the latest on or before it
144	     *  (a rate with no from-date applies from the beginning of time); none applies when there is no
145	     *  such rate, or when that one's to-date is before the date. When none applies on the sheet, the
146	     *  parent sheet's is taken, then the parent's parent's, up to {@link #PARENT_LEVELS} levels up,
147	     *  then those of the sheet it was cloned from (see {@link #fallbacks}); empty when none applies on
148	     *  any of them. */
149	    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
150	        return rateOn(sheetId, grade, date, null);
151	    }
152	
153	    /** The grade's rate in force on a date as the sheet's rates stood at the end of a day (null: as
154	     *  they stand now), falling back to the rates of the parent sheets it had then, as they stand now. */
155	    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date, LocalDate asOf) {
156	        return rateFor(sheetId, grade, date, null, asOf);
157	    }
158	
159	    /** The grade's rate that applies to a claim (null: to no claim in particular) on a date, as
160	     *  {@link #rateOn} finds it, but of the rates that apply to the claim only: a forward-only rate
161	     *  saved before the claim was added is passed over, the claim keeping the version of it, if any,
162	     *  that applied to it (see {@link Rate#appliesTo}). */
163	    public Optional<Rate> rateFor(String sheetId, String grade, LocalDate date, Long claimId, LocalDate asOf) {
164	        Optional<Rate> own = ownRateFor(sheetId, grade, date, claimId, asOf);
165	        if (own.isPresent()) {
166	            return own;
167	        }
168	        // Read as of a day, the sheet falls back to the parents it had at the end of it, their rates as
169	        // they stand now: a parent keeps its own today, so its history does not follow the sheet's.
170	        for (String ancestor : fallbacks(sheetId, asOf)) {
171	            Optional<Rate> theirs = ownRateFor(ancestor, grade, date, claimId, null);
172	            if (theirs.isPresent()) {
173	                return theirs;
174	            }
175	        }
176	        return Optional.empty();
177	    }
