179	    private Optional<Rate> ownRateFor(String sheetId, String grade, LocalDate date, Long claimId, LocalDate asOf) {
180	        List<Rate> theirs = asOf == null ? rates.findBySheetIdAndGradeOrderByFromAsc(sheetId, grade)
181	                : history.rates(sheetId, grade, asOf);
182	        return inForce(theirs.stream().map(rate -> versionFor(rate, claimId)).flatMap(Optional::stream).toList(),
183	                date);
184	    }
185	
186	    /** The newest version of a rate that applies to a claim; empty when none of them does. */
187	    private Optional<Rate> versionFor(Rate rate, Long claimId) {
188	        if (rate.appliesTo(claimId)) {
189	            return Optional.of(rate);
190	        }
191	        return earlier(rate).stream().filter(version -> version.appliesTo(claimId)).findFirst();
192	    }
193	
194	    private static Optional<Rate> inForce(List<Rate> theirs, LocalDate date) {
195	        return theirs.stream()
196	                .filter(rate -> rate.appliesOn(date))
197	                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
198	                .filter(rate -> !rate.endedBy(date));
199	    }
200	
201	    /** Set the rate for a grade from a date (null: from the beginning of time) through a date (null:
202	     *  with no end). When the grade has a rate from that date, the value it held is kept as an older
203	     *  version and the new one becomes its newest version, the one in force. A rate from a date on or
204	     *  after the sheet's today is forward-only: it applies only to claims added after it is saved. A
205	     *  to-date before the from-date is refused. */
206	    @Transactional
207	    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
208	        if (from != null && to != null && to.isBefore(from)) {
209	            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
210	        }
211	        sheets.load(sheetId);
212	        if (!grades.isGrade(sheetId, grade)) {
213	            throw new RateRefusedException("There is no grade " + grade);
214	        }
215	        BigDecimal scaled = rate.setScale(2, RoundingMode.UNNECESSARY);
216	        Long forwardAfter = from != null && !from.isBefore(sheets.today(sheetId))
217	                ? jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM claim", Long.class)
218	                : null;
219	        Optional<Rate> had = from == null
220	                ? rates.findBySheetIdAndGradeAndFromIsNull(sheetId, grade)
221	                : rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from);
222	        Rate saved = had
223	                .map(existing -> {
224	                    versions.save(new RateVersion(existing, sheets.today(sheetId), user));
225	                    existing.newVersion(scaled, to, forwardAfter);
226	                    return existing;
227	                })
228	                .orElseGet(() -> {
229	                    Rate made = new Rate(sheetId, grade, from, to, scaled);
230	                    made.setForwardAfter(forwardAfter);
231	                    return made;
232	                });
233	        saved = rates.saveAndFlush(saved);
234	        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
235	                + " rate=" + saved.getRate().toPlainString() + (from != null ? " from=" + from : "")
236	                + (to != null ? " to=" + to : ""));
237	        return saved;
238	    }
239	
240	    /** A steward withdraws the newest version of a grade's rate from a date (null: from the beginning
241	     *  of time): the version before it, when there is one, is in force again; with none the rate is
242	     *  gone. Anyone else, or a grade with no rate from that date, is refused. */
243	    @Transactional
244	    public void withdraw(String sheetId, String user, String grade, LocalDate from) {
245	        sheets.load(sheetId);
246	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
247	            throw new RateRefusedException(user + " is not a steward: only a steward withdraws a rate");
248	        }
249	        Rate rate = (from == null
250	                ? rates.findBySheetIdAndGradeAndFromIsNull(sheetId, grade)
251	                : rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from))
252	                .orElseThrow(() -> new RateRefusedException("Grade " + grade + " has no rate from that date"));
253	        List<RateVersion> older = versions.findByRateIdOrderByVersionAsc(rate.getId());
254	        if (older.isEmpty()) {
255	            history.rateWithdrawn(rate);
256	            rates.delete(rate);
257	            rates.flush();
258	        } else {
259	            RateVersion previous = older.get(older.size() - 1);
260	            versions.delete(previous);
261	            rate.restore(previous.getRate(), previous.getTo(), previous.getVersion(), previous.getForwardAfter());
262	            rates.saveAndFlush(rate);
263	        }
264	        audit.recordOnCommit("RATE_WITHDRAWN sheet=" + sheetId + " by=" + user + " grade=" + grade
265	                + (from != null ? " from=" + from : ""));
266	    }
267	}
