46	    /** A claim as the screen shows it; the amount and the due fixed on settling (null when none
47	     *  was) are strings with two decimals; openedBy is null for a claim never opened; stated tells
48	     *  whether a statement bound the claim, statedDue the due it bound it to, late charge included (null when none);
49	     *  corrects is the number of the claim a correction corrects (null when it is not one); roundsBy
50	     *  is the date its live figures round by against the sheet's policy date (its own date, or for a
51	     *  correction the date of the claim it corrects); dueBy is the date it is due by, fixed when it was
52	     *  added; log is its status log, oldest first, one line per status it has had; deferredUntil is
53	     *  the date it was deferred until (null when it never was); proofs is how many proofs were added
54	     *  to it; splitFrom is the number of the claim it was split off (null when it was not); lockedBy is
55	     *  the user whose open editor locks it (null when no one's does); lateEntry is whether it was
56	     *  added while its period was soft-closed; remindedOn is the last day a reminder was written for it
57	     *  (null when none was); ref is its external reference (null when it has none); tags are its tags,
58	     *  sorted (empty when it has none); voidReason is the reason it was voided with (null when none
59	     *  was given); comments are its comments, oldest first, each as <user> on <date>: <text>; batch
60	     *  is the number of the settle batch that settled it (null when a bulk settle did not); lines are
61	     *  its lines, oldest first, each as <label> <qty> x <unit> (empty when it has none); waived is
62	     *  whether a steward waived its late charge; proofsReceipt and proofsPhoto are how many of its
63	     *  proofs are receipts and photos; held is whether the claim itself is held; shares are the
64	     *  shares of it other people hold, in the order it was shared (empty when it has none). */
65	    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note,
66	            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
67	            String statedDue, String corrects, LocalDate roundsBy, LocalDate dueBy, List<String> log,
68	            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry,
69	            LocalDate remindedOn, String ref, List<String> tags, String voidReason, List<String> comments,
70	            Long batch, List<String> lines, boolean waived, int proofsReceipt, int proofsPhoto, boolean held,
71	            List<ShareView> shares, String reviewAssignee) {
72	        public static ClaimView of(Claim claim, LocalDate roundsBy, List<String> log, List<String> comments) {
73	            return of(claim, roundsBy, log, comments, List.of());
74	        }
75	
76	        public static ClaimView of(Claim claim, LocalDate roundsBy, List<String> log, List<String> comments,
77	                List<String> lines) {
78	            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
79	                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
80	                    claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : null,
81	                    claim.getOpenedBy(), claim.isStated(),
82	                    claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null,
83	                    claim.getCorrects(), roundsBy, claim.getDueBy(), log, claim.getDeferredUntil(),
84	                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(),
85	                    claim.getRemindedOn(), claim.getRef(), claim.getTags(),
86	                    claim.getVoidReason(), comments, claim.getBatch(), lines, claim.isWaived(),
87	                    claim.getProofsReceipt(), claim.getProofsPhoto(), claim.isHeld(),
88	                    claim.getShares().stream().map(ShareView::of).toList(), claim.getReviewAssignee());
89	        }
90	    }
