247	    /** The sheet's claims, newest first: as they stand now, or as they stood at the end of the
248	     *  screen's as-of date (those added by then, each with its status log up to then). */
249	    @GetMapping("/claims")
250	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
251	            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
252	        String sheet = sheetId.trim();
253	        LocalDate asOf = AsOf.parse(asOfHeader);
254	        Map<Long, List<String>> logs = service.logsOf(sheet, asOf);
255	        Map<Long, List<String>> comments = service.commentsOf(sheet, asOf);
256	        Map<Long, List<String>> lines = service.linesOf(sheet);
257	        List<Claim> claims = asOf == null ? service.list(sheet) : history.claims(service.list(sheet), asOf);
258	        return claims.stream()
259	                .map(claim -> ClaimView.of(claim, service.roundsBy(sheet, claim), logs.getOrDefault(claim.getId(), List.of()),
260	                        comments.getOrDefault(claim.getId(), List.of()), lines.getOrDefault(claim.getId(), List.of())))
261	                .toList();
262	    }
