18:/** Finds the claims a person has more than once: the same date and amount. */
19:@Service
20:public class DuplicateClaimService {
22:    /** A person's date and amount with two or more claims (VOID and DELETED ones left out). */
23:    public record Duplicate(String name, String date, String amount, int count) {
24:    }
26:    private record Key(LocalDate date, BigDecimal amount) implements Comparable<Key> {
27:        @Override
28:        public int compareTo(Key other) {
29:            int byDate = date.compareTo(other.date);
30:            return byDate != 0 ? byDate : amount.compareTo(other.amount);
31:        }
32:    }
34:    private final PersonRepository people;
35:    private final ClaimRepository claims;
37:    public DuplicateClaimService(PersonRepository people, ClaimRepository claims) {
38:        this.people = people;
39:        this.claims = claims;
40:    }
42:    /** The sheet's duplicate claims: people in list order, then by date, then by amount. */
43:    @Transactional(readOnly = true)
44:    public List<Duplicate> duplicates(String sheetId) {
45:        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByListedDesc(sheetId).stream()
46:                .filter(c -> c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
47:                .collect(Collectors.groupingBy(Claim::getPersonId));
48:        List<Duplicate> found = new ArrayList<>();
49:        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
50:            Map<Key, Integer> counts = new TreeMap<>();
51:            for (Claim claim : byPerson.getOrDefault(person.getId(), List.of())) {
52:                counts.merge(new Key(claim.getDate(), claim.getAmount().stripTrailingZeros()), 1, Integer::sum);
53:            }
54:            counts.forEach((key, count) -> {
55:                if (count >= 2) {
56:                    found.add(new Duplicate(person.getName(), key.date().toString(),
57:                            key.amount().setScale(2).toPlainString(), count));
58:                }
59:            });
60:        }
61:        return found;
62:    }
63:}
