21:/** Opens a claim per pasted line of name,amount,date,note for a person named on the sheet; a
22: *  note ending in " #<reference>" gives the claim that external reference. A line naming the person,
23: *  date and note of one of their claims as they stood before the paste (not VOID or DELETED) updates
24: *  that claim, the newest such DRAFT, to the line's amount instead of adding one; a line whose matches
25: *  hold no DRAFT is refused. Each claim is then opened as the open button would. Every line is checked
26: *  first; the whole paste is one change, so one refused line, or one refused open, changes nothing. */
27:@Service
28:public class PasteService {
30:    /** The most a claim's note holds, as on the claim form. */
31:    private static final int NOTE_MAX = 2000;
33:    /** The most a claim's external reference holds, as on the claim form. */
34:    private static final int REF_MAX = 255;
36:    /** A pasted line, read: the person it names and the claim's figures (a null date: the sheet's entry
37:     *  date, else its today; a null reference: none). */
38:    private record Line(int at, Person person, BigDecimal amount, LocalDate date, String note, String ref) {
39:    }
41:    private final PersonRepository people;
42:    private final ClaimService claims;
43:    private final RollupService rollups;
44:    private final SettingService settings;
46:    public PasteService(PersonRepository people, ClaimService claims, RollupService rollups,
47:            SettingService settings) {
48:        this.people = people;
49:        this.claims = claims;
50:        this.rollups = rollups;
51:        this.settings = settings;
52:    }
54:    /** Add or update the pasted claims in the order of their lines, opening each (so they are
55:     *  numbered in that order); blank lines are skipped. The claims are returned in line order. */
56:    @Transactional
57:    public List<Claim> paste(String sheetId, String user, String text) {
58:        List<Line> lines = new ArrayList<>();
59:        Set<String> refs = new HashSet<>();
60:        int at = 0;
61:        for (String raw : text.split("\\r?\\n")) {
62:            at++;
63:            if (!raw.isBlank()) {
64:                Line line = read(sheetId, at, raw);
65:                if (line.ref() != null && (!refs.add(Claim.keyOf(line.ref()))
66:                        || claims.refInUse(sheetId, line.ref(), null))) {
67:                    throw new PasteRefusedException("Line " + at + ": the reference " + line.ref() + " is already used");
68:                }
69:                lines.add(line);
70:            }
71:        }
72:        if (lines.isEmpty()) {
73:            throw new PasteRefusedException("Nothing to add");
74:        }
75:        List<Claim> targets = targets(sheetId, lines);
76:        List<Claim> opened = new ArrayList<>();
77:        for (int i = 0; i < lines.size(); i++) {
78:            Line line = lines.get(i);
79:            Claim target = targets.get(i);
80:            opened.add(rollups.track(sheetId, user, () -> {
81:                Claim claim = target == null
82:                        ? claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null,
83:                                line.ref())
84:                        : edited(sheetId, user, target, line);
85:                return claims.changeStatus(sheetId, user, claim.getPersonId(), claim.getId(), ClaimStatus.OPEN);
86:            }));
87:        }
88:        return opened;
89:    }
91:    /** The claim each line updates, as the claims stood before the paste (null: the line adds one): the
92:     *  newest DRAFT of the person with the line's date and note; a line matching only claims that are
93:     *  not DRAFTs, or a DRAFT an earlier line of the paste already updates, is refused. */
94:    private List<Claim> targets(String sheetId, List<Line> lines) {
95:        List<Claim> before = claims.list(sheetId);
96:        LocalDate defaultDate = settings.defaultClaimDate(sheetId);
97:        Set<Long> taken = new HashSet<>();
98:        List<Claim> targets = new ArrayList<>();
99:        for (Line line : lines) {
100:            LocalDate on = line.date() != null ? line.date() : defaultDate;
101:            List<Claim> matches = before.stream()
102:                    .filter(c -> c.getPersonId().equals(line.person().getId()) && on.equals(c.getDate())
103:                            && line.note().equals(c.getNote())
104:                            && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
105:                    .toList();
106:            if (matches.isEmpty()) {
107:                targets.add(null);
108:                continue;
109:            }
110:            Claim draft = matches.stream().filter(c -> c.getStatus() == ClaimStatus.DRAFT).findFirst()
111:                    .orElseThrow(() -> new PasteRefusedException(
112:                            "Line " + line.at() + ": it matches a claim that is not a DRAFT"));
113:            if (!taken.add(draft.getId())) {
114:                throw new PasteRefusedException("Line " + line.at() + ": its DRAFT is updated by an earlier line");
115:            }
116:            targets.add(draft);
117:        }
118:        return targets;
119:    }
121:    /** A matched DRAFT edited to the line's amount (and its reference, when it gives one); left as it
122:     *  is when that changes nothing. */
123:    private Claim edited(String sheetId, String user, Claim draft, Line line) {
124:        String ref = line.ref() != null ? line.ref() : draft.getRef();
125:        if (draft.getAmount().compareTo(line.amount()) == 0 && Objects.equals(ref, draft.getRef())) {
126:            return draft;
127:        }
128:        return claims.update(sheetId, user, draft.getPersonId(), draft.getId(), line.amount(), draft.getDate(),
129:                draft.getNote(), draft.getCorrects(), ref, String.join(",", draft.getTags()));
130:    }
132:    /** One line as the claim form reads it: an amount of 0.00 or more with up to two decimals, a
133:     *  date (blank: the sheet's entry date, else its today) and a note (absent: empty) that may hold commas,
134:     *  ending in " #<reference>" when it gives the claim an external reference. */
135:    private Line read(String sheetId, int at, String raw) {
136:        String[] fields = raw.split(",", 4);
137:        if (fields.length < 3) {
138:            throw new PasteRefusedException("Line " + at + " needs name,amount,date");
139:        }
140:        String name = fields[0].trim();
141:        Person person = name.isEmpty() ? null : people.findByName(sheetId, name).orElse(null);
142:        if (person == null) {
143:            throw new PasteRefusedException("Line " + at + ": no person " + name + " on the sheet");
144:        }
145:        BigDecimal amount;
146:        try {
147:            amount = new BigDecimal(fields[1].trim());
148:        } catch (NumberFormatException e) {
149:            throw new PasteRefusedException("Line " + at + ": the amount is not a number");
150:        }
151:        if (amount.signum() < 0 || amount.scale() > 2 || amount.precision() - amount.scale() > 10) {
152:            throw new PasteRefusedException("Line " + at + ": the amount must be 0.00 or more, with up to two decimals");
153:        }
154:        LocalDate date;
155:        try {
156:            date = fields[2].isBlank() ? null : LocalDate.parse(fields[2].trim());
157:        } catch (DateTimeParseException e) {
158:            throw new PasteRefusedException("Line " + at + ": the date is not a date");
159:        }
160:        String note = fields.length > 3 ? fields[3].trim() : "";
161:        String ref = null;
162:        int hash = note.lastIndexOf(" #");
163:        if (hash >= 0) {
164:            ref = ClaimService.refOf(note.substring(hash + 2));
165:            note = note.substring(0, hash).trim();
166:        }
167:        if (ref != null && ref.length() > REF_MAX) {
168:            throw new PasteRefusedException("Line " + at + ": the reference is too long");
169:        }
170:        if (note.length() > NOTE_MAX) {
171:            throw new PasteRefusedException("Line " + at + ": the note is too long");
172:        }
173:        return new Line(at, person, amount, date, note, ref);
174:    }
175:}
