12:/** The claim templates on a sheet: each a name, an amount and a note a claim can be added from. */
13:@Service
14:public class ClaimTemplateService {
16:    private final ClaimTemplateRepository templates;
17:    private final SheetService sheets;
18:    private final Audit audit;
20:    public ClaimTemplateService(ClaimTemplateRepository templates, SheetService sheets, Audit audit) {
21:        this.templates = templates;
22:        this.sheets = sheets;
23:        this.audit = audit;
24:    }
26:    /** The sheet's claim templates, sorted by name. */
27:    public List<ClaimTemplate> list(String sheetId) {
28:        return templates.findBySheetIdOrderByNameAsc(sheetId);
29:    }
31:    /** The sheet's template of this name (trimmed); none is not found. */
32:    public ClaimTemplate get(String sheetId, String name) {
33:        String key = name == null ? "" : name.trim();
34:        return templates.findBySheetIdAndName(sheetId, key)
35:                .orElseThrow(() -> new NoSuchElementException("No template " + key));
36:    }
38:    /** Save a template: its name and note trimmed, its amount one the claim form adds without a
39:     *  correction (0 or more, up to two decimals). Saving a name again replaces that template. A
40:     *  blank name or such an amount is refused. The sheet is held locked so the same name saved at
41:     *  the same moment is checked against itself. */
42:    @Transactional
43:    public ClaimTemplate save(String sheetId, String user, String name, BigDecimal amount, String note) {
44:        String key = name == null ? "" : name.trim();
45:        if (key.isEmpty()) {
46:            throw new ClaimTemplateRefusedException("A template needs a name");
47:        }
48:        if (amount == null || amount.signum() < 0 || amount.stripTrailingZeros().scale() > 2) {
49:            throw new ClaimTemplateRefusedException("A template's amount is 0 or more with up to two decimals");
50:        }
51:        BigDecimal scaled = amount.setScale(2, RoundingMode.UNNECESSARY);
52:        String text = note == null ? "" : note.trim();
53:        sheets.lock(sheetId);
54:        ClaimTemplate template = templates.findBySheetIdAndName(sheetId, key)
55:                .orElseGet(() -> new ClaimTemplate(sheetId, key, scaled, text));
56:        template.replace(scaled, text);
57:        ClaimTemplate saved = templates.saveAndFlush(template);
58:        audit.recordOnCommit("TEMPLATE_SAVED sheet=" + sheetId + " by=" + user + " name=" + key
59:                + " amount=" + scaled.toPlainString() + " note=" + text);
60:        return saved;
61:    }
62:}

