    18	/**
    19	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
    20	 * so tests can assert side-effects by reading that file — the second test-assertion channel
    21	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
    22	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
    23	 *
    24	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
    25	 * SYNC) so a test reads the record immediately.
    26	 */
    27	@Service
    28	public class Audit {
    29	
    30	    /** The events that only report figures: they never name a delegating steward. A SNAPSHOT is not
    31	     *  one of them: it records the user's own change of the sheet's today. */
    32	    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");
    33	
    34	    private final Path file;
    35	    private final ObjectProvider<SettingService> settings;
    36	
    37	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<SettingService> settings) {
    38	        this.file = Path.of(path);
    39	        this.settings = settings;
    40	    }
    41	
    42	    /**
    43	     * The record as written: a change made by a user acting as a steward by a delegation in force on
    44	     * the sheet's today ends with for=<the steward who delegated>; a record that only reports figures
    45	     * does not.
    46	     */
    47	    private String delegated(String entry) {
    48	        String event = entry.split(" ", 2)[0];
    49	        int sheetAt = entry.indexOf(" sheet=");
    50	        int byAt = entry.indexOf(" by=");
    51	        if (FIGURES_ONLY.contains(event) || sheetAt < 0 || byAt < sheetAt) {
    52	            return entry;
    53	        }
    54	        String sheetId = entry.substring(sheetAt + " sheet=".length(), byAt);
    55	        int byEnd = entry.indexOf(' ', byAt + " by=".length());
    56	        String by = entry.substring(byAt + " by=".length(), byEnd < 0 ? entry.length() : byEnd);
    57	        return settings.getObject().delegatedBy(sheetId, by).map(steward -> entry + " for=" + steward).orElse(entry);
    58	    }
    59	
    60	    /** Append one audit record. Tests assert the exact line(s) in the file. */
    61	    public synchronized void record(String entry) {
    62	        try {
    63	            Path parent = file.toAbsolutePath().getParent();
    64	            if (parent != null) {
    65	                Files.createDirectories(parent);
    66	            }
    67	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
    68	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
    69	        } catch (IOException e) {
    70	            throw new UncheckedIOException(e);
    71	        }
    72	    }
    73	
    74	    /**
    75	     * Append one audit record once the current transaction commits, so a change that is refused or
    76	     * rolled back writes nothing; outside a transaction it is appended at once.
    77	     */
    78	    public void recordOnCommit(String change) {
    79	        String entry = delegated(change);
    80	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
    81	            record(entry);
    82	            return;
    83	        }
    84	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
    85	            @Override
    86	            public void afterCommit() {
    87	                record(entry);
    88	            }
    89	        });
    90	    }
    91	
    92	    /** Every line the audit file holds, in the order they were appended; none when there is no file yet. */
    93	    public synchronized List<String> lines() {
    94	        try {
    95	            return Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
    96	        } catch (IOException e) {
    97	            throw new UncheckedIOException(e);
    98	        }
    99	    }
   100	
   101	    /** Truncate the audit file. */
   102	    public synchronized void clear() {
   103	        try {
   104	            Files.deleteIfExists(file);
   105	        } catch (IOException e) {
   106	            throw new UncheckedIOException(e);
   107	        }
   108	    }
   109	}
