2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.time.format.DateTimeParseException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import net.officefloor.hq.app.rollup.RollupService;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/** Sets a rate per pasted line of grade,rate,from,to (from and to may be absent or blank), each as the
13	 *  rate form would. Every line is checked first; the whole paste is one change, so one refused line
14	 *  sets nothing. */
15	@Service
16	public class RateImportService {
17	
18	    /** A pasted line, read: the rate's fields (null from: from the beginning of time; null to: no end). */
19	    private record Line(String grade, BigDecimal rate, LocalDate from, LocalDate to) {
20	    }
21	
22	    private final RateService rates;
23	    private final RollupService rollups;
24	
25	    public RateImportService(RateService rates, RollupService rollups) {
26	        this.rates = rates;
27	        this.rollups = rollups;
28	    }
29	
30	    /** Set the pasted rates in the order of their lines, each replacing the grade's rate from the same
31	     *  date; blank lines are skipped. The rates set, in the order of their lines. */
32	    @Transactional
33	    public List<Rate> importRates(String sheetId, String user, String text) {
34	        List<Line> lines = new ArrayList<>();
35	        int at = 0;
36	        for (String raw : text.split("\\r?\\n")) {
37	            at++;
38	            if (!raw.isBlank()) {
39	                lines.add(read(at, raw));
40	            }
41	        }
42	        if (lines.isEmpty()) {
43	            throw new RateRefusedException("Nothing to import");
44	        }
45	        List<Rate> set = new ArrayList<>();
46	        for (Line l : lines) {
47	            set.add(rollups.track(sheetId, user, () -> rates.set(sheetId, user, l.grade(), l.from(), l.to(), l.rate())));
48	        }
49	        return set;
50	    }
51	
52	    /** One line as the rate form reads it: a grade of A, B or C, a percent of 0.00 or more with up to
53	     *  two decimals, and a from-date and a to-date (each blank: none) with the to-date not before the
54	     *  from-date, each trimmed. */
55	    private static Line read(int at, String raw) {
56	        String[] fields = raw.split(",", -1);
57	        if (fields.length < 2 || fields.length > 4) {
58	            throw new RateRefusedException("Line " + at + " needs grade,rate,from,to");
59	        }
60	        String grade = fields[0].trim();
61	        if (!grade.matches("[A-Z]{1,3}")) {
62	            throw new RateRefusedException("Line " + at + ": the grade must be one to three capital letters");
63	        }
64	        String rate = fields[1].trim();
65	        if (!rate.matches("\\d{1,5}(\\.\\d{1,2})?")) {
66	            throw new RateRefusedException("Line " + at + ": the rate must be 0.00 or more with up to two decimals");
67	        }
68	        LocalDate from = date(at, fields.length > 2 ? fields[2] : "");
69	        LocalDate to = date(at, fields.length > 3 ? fields[3] : "");
70	        if (from != null && to != null && to.isBefore(from)) {
71	            throw new RateRefusedException("Line " + at + ": the to-date cannot be before the from-date");
72	        }
73	        return new Line(grade, new BigDecimal(rate), from, to);
74	    }
75	
76	    private static LocalDate date(int at, String field) {
77	        String text = field.trim();
78	        if (text.isEmpty()) {
79	            return null;
80	        }
81	        try {
82	            return LocalDate.parse(text);
83	        } catch (DateTimeParseException e) {
84	            throw new RateRefusedException("Line " + at + ": " + text + " is not a date");
85	        }
86	    }
87	}
