1	package net.officefloor.hq.app.person;
2	
3	import java.util.ArrayList;
4	import java.util.HashSet;
5	import java.util.List;
6	import java.util.Locale;
7	import java.util.Set;
8	import net.officefloor.hq.app.rollup.RollupService;
9	import net.officefloor.hq.app.setting.SettingService;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	/** Adds a person per pasted line of name,grade,terms,contact (terms and contact may be absent or
14	 *  blank; a blank grade takes the sheet's default grade), each as the person form would; a line whose name matches a person on the sheet (by name or
15	 *  alias, as names are compared) updates them as their editor would instead. Every line is checked
16	 *  first; the whole paste is one change, so one refused line imports nothing. */
17	@Service
18	public class PersonImportService {
19	
20	    /** The most a name or contact holds, as on the person form. */
21	    private static final int TEXT_MAX = 200;
22	
23	    /** The most days a person's own terms run to, as on the person form. */
24	    private static final int TERMS_MAX = 36500;
25	
26	    /** A pasted line, read: the person's fields (null terms: none; null contact: none). */
27	    private record Line(String name, String grade, Integer terms, String contact) {
28	    }
29	
30	    /** What an import did: the people it added and those it updated, each in the order of their lines. */
31	    public record Result(List<Person> added, List<Person> updated) {
32	    }
33	
34	    private final PersonService people;
35	    private final PersonRepository repository;
36	    private final RollupService rollups;
37	    private final SettingService settings;
38	
39	    public PersonImportService(PersonService people, PersonRepository repository, RollupService rollups,
40	            SettingService settings) {
41	        this.settings = settings;
42	        this.people = people;
43	        this.repository = repository;
44	        this.rollups = rollups;
45	    }
46	
47	    /** Add or update the pasted people in the order of their lines; blank lines are skipped. A name or
48	     *  contact repeated within the paste, two lines for the same person, or a name or contact already in
49	     *  use as the form judges, refuses the whole paste. */
50	    @Transactional
51	    public Result importPeople(String sheetId, String user, String text) {
52	        List<Line> lines = new ArrayList<>();
53	        Set<String> names = new HashSet<>();
54	        Set<String> contacts = new HashSet<>();
55	        String defaultGrade = settings.defaultGrade(sheetId);
56	        int at = 0;
57	        for (String raw : text.split("\\r?\\n")) {
58	            at++;
59	            if (raw.isBlank()) {
60	                continue;
61	            }
62	            Line line = read(at, raw, defaultGrade);
63	            if (!names.add(line.name().toLowerCase(Locale.ROOT))) {
64	                throw new ImportRefusedException("Line " + at + ": the name " + line.name() + " is repeated");
65	            }
66	            if (line.contact() != null && !contacts.add(line.contact())) {
67	                throw new ImportRefusedException("Line " + at + ": the contact " + line.contact() + " is repeated");
68	            }
69	            lines.add(line);
70	        }
71	        if (lines.isEmpty()) {
72	            throw new ImportRefusedException("Nothing to import");
73	        }
74	        // Each person is added or updated as the form does it, so a name or contact already in use on the
75	        // sheet (or its tree) refuses the paste, and the transaction takes back the changes before it.
76	        List<Person> added = new ArrayList<>();
77	        List<Person> updated = new ArrayList<>();
78	        Set<Long> matched = new HashSet<>();
79	        at = 0;
80	        for (Line l : lines) {
81	            at++;
82	            Person match = repository.findByName(sheetId, l.name()).orElse(null);
83	            if (match == null) {
84	                added.add(rollups.track(sheetId, user,
85	                        () -> people.add(sheetId, user, l.name(), l.grade(), l.terms(), l.contact())));
86	                continue;
87	            }
88	            if (!matched.add(match.getId())) {
89	                throw new ImportRefusedException("Line " + at + ": " + match.getName() + " is repeated");
90	            }
91	            // The grade is given from the sheet's today; terms and contact are kept unless the line gives them.
92	            Integer terms = l.terms() != null ? l.terms() : people.termsToday(match);
93	            String contact = l.contact() != null ? l.contact() : match.getContact();
94	            updated.add(rollups.track(sheetId, user, () -> people.update(sheetId, user, match.getId(),
95	                    match.getVersion(), match.getName(), l.grade(), null, terms, contact)));
96	        }
97	        return new Result(added, updated);
98	    }
99	
100	    /** One line as the person form reads it: a name that is not blank, a grade of A, B or C (blank: the default grade), terms of
101	     *  a whole number of days (blank: none) and a contact (blank: none), each trimmed. */
102	    private static Line read(int at, String raw, String defaultGrade) {
103	        String[] fields = raw.split(",", -1);
104	        if (fields.length < 2 || fields.length > 4) {
105	            throw new ImportRefusedException("Line " + at + " needs name,grade,terms,contact");
106	        }
107	        String name = fields[0].trim();
108	        if (name.isEmpty() || name.length() > TEXT_MAX) {
109	            throw new ImportRefusedException("Line " + at + ": the name must not be blank or too long");
110	        }
111	        String grade = fields[1].trim();
112	        if (grade.isEmpty()) {
113	            grade = defaultGrade;
114	        }
115	        if (!grade.matches("[A-Z]{1,3}")) {
116	            throw new ImportRefusedException("Line " + at + ": the grade must be one to three capital letters");
117	        }
118	        String termsText = fields.length > 2 ? fields[2].trim() : "";
119	        Integer terms = null;
120	        if (!termsText.isEmpty()) {
121	            if (!termsText.matches("\\d{1,5}") || Integer.parseInt(termsText) > TERMS_MAX) {
122	                throw new ImportRefusedException("Line " + at + ": the terms must be a whole number of days");
123	            }
124	            terms = Integer.parseInt(termsText);
125	        }
126	        String contact = fields.length > 3 ? fields[3].trim().toLowerCase(Locale.ROOT) : "";
127	        if (contact.length() > TEXT_MAX) {
128	            throw new ImportRefusedException("Line " + at + ": the contact is too long");
129	        }
130	        return new Line(name, grade, terms, contact.isEmpty() ? null : contact);
131	    }
132	}
