178	        }
179	        for (PersonPatron naming : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
180	            if (!naming.getPatronId().equals(from.getId())) {
181	                continue;
182	            }
183	            if (naming.getPersonId().equals(into.getId())
184	                    || patrons.existsByPersonIdAndPatronId(naming.getPersonId(), into.getId())) {
185	                patrons.delete(naming);
186	                patrons.flush();
187	            } else {
188	                naming.setPatronId(into.getId());
189	                patrons.saveAndFlush(naming);
190	            }
191	        }
192	
193	        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
194	            Optional<PoolMember> already = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
195	            if (already.isPresent()) {
196	                already.get().addShare(member.getShare());
197	                poolMembers.delete(member);
198	                poolMembers.flush();
199	                poolMembers.saveAndFlush(already.get());
200	            } else {
201	                member.setPersonId(into.getId());
202	                poolMembers.saveAndFlush(member);
203	            }
204	        }
205	        crews.merge(from.getId(), into.getId());
206	
207	        // The figures fixed for them in closed and soft-closed periods, and their opening balances,
208	        // become the other's.
209	        List<Period> sheetPeriods = periods.findBySheetIdOrderByFromAsc(sheetId);
210	        sheetPeriods.forEach(period -> period.fold(from.getId(), into.getId()));
211	        periods.saveAllAndFlush(sheetPeriods);
212	
213	        // Their statements become the other's, before the other's own (when they have any), so the
214	        // other's last statement stays theirs.
215	        List<Statement> theirStatements = statements.inOrder(sheetId, from.getId());
216	        List<Statement> ownStatements = statements.inOrder(sheetId, into.getId());
217	        long first = ownStatements.isEmpty() ? Long.MAX_VALUE
218	                : ownStatements.get(0).getOrder() - theirStatements.size();
219	        for (int i = 0; i < theirStatements.size(); i++) {
220	            Statement statement = theirStatements.get(i);
221	            statement.moveTo(into.getId(), ownStatements.isEmpty() ? statement.getOrder() : first + i);
222	        }
223	        statements.saveAllAndFlush(theirStatements);
224	        holds.deleteAll(holds.findByPersonIdOrderByIdAsc(from.getId()));
225	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
226	        from.setContact(null);
227	        from.mergeInto(into.getId());
228	        people.saveAndFlush(from);
229	
230	        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user + " from=" + from.getName()
231	                + " into=" + into.getName());
232	        return nameAlias;
233	    }
