92	    /** A steward undoes a person's transfer to this sheet on the same sheet's today they arrived: they
93	     *  are transferred back to the sheet they came from, exactly as a transfer, and this sheet then
94	     *  writes its line. Anyone but a steward, a later day, or a person who did not arrive by transfer
95	     *  is refused. */
96	    @Transactional
97	    public void undo(String sheetId, String user, Long id) {
98	        Person person = people.findByIdAndSheetId(id, sheetId)
99	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
100	        String from = person.getOriginSheetId();
101	        if (from == null) {
102	            throw new TransferRefusedException(person.getName() + " did not arrive by transfer");
103	        }
104	        Stream.of(sheetId, from).sorted().distinct().forEach(sheets::lock);
105	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
106	            throw new TransferRefusedException(user + " is not a steward: only a steward undoes a transfer");
107	        }
108	        if (!sheets.today(sheetId).equals(person.getAddedOn())) {
109	            throw new TransferRefusedException("A transfer is undone only on the day the person arrived");
110	        }
111	        String name = person.getName();
112	        rollups.track(sheetId, user, () -> {
113	            transfer(sheetId, user, id, from);
114	            audit.recordOnCommit("PERSON_TRANSFER_UNDONE sheet=" + sheetId + " by=" + user + " name=" + name
115	                    + " to=" + from);
116	            return null;
117	        });
118	    }
