120	    private void move(String sheetId, String user, Long id, String to) {
121	        Person person = people.findByIdAndSheetId(id, sheetId)
122	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
123	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
124	            throw new TransferRefusedException(user + " is not a steward: only a steward transfers people");
125	        }
126	        if (person.isRetired()) {
127	            throw new TransferRefusedException("A retired person is not transferred");
128	        }
129	        if (to.equals(sheetId)) {
130	            throw new TransferRefusedException(person.getName() + " is on " + sheetId + " already");
131	        }
132	        if (sheets.isArchived(sheetId) || sheets.isArchived(to)) {
133	            throw new TransferRefusedException("An archived sheet takes no transfer");
134	        }
135	        List<PersonAlias> theirAliases = aliases.findByPersonIdOrderByIdAsc(person.getId());
136	        List<String> theirNames = Stream.concat(Stream.of(person.getName()),
137	                theirAliases.stream().map(PersonAlias::getAlias)).toList();
138	        List<Long> sameNamed = theirNames.stream().map(name -> people.findByName(to, name))
139	                .flatMap(Optional::stream).map(Person::getId).distinct().toList();
140	        Long intoId = null;
141	        if (sameNamed.size() > 1) {
142	            throw new NameInUseException(person.getName());
143	        } else if (sameNamed.size() == 1) {
144	            // Already on the other sheet by a name or alias: they arrive and are merged into them.
145	            intoId = sameNamed.get(0);
146	            if (people.findById(intoId).orElseThrow().isRetired()) {
147	                throw new TransferRefusedException("A retired person is not merged into");
148	            }
149	        } else {
150	            boolean nameTaken = theirNames.stream()
151	                    .anyMatch(name -> people.nameInUse(to, name, null) || aliases.aliasInUse(to, name));
152	            if (nameTaken) {
153	                throw new NameInUseException(person.getName());
154	            }
155	            if (person.getContact() != null && people.contactInUse(to, person.getContact(), null)) {
156	                throw new ContactInUseException(person.getContact());
157	            }
158	        }
159	
160	        List<Claim> theirClaims = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, person.getId());
161	        Map<Long, LocalDate> openedOn = new HashMap<>();
162	        for (Claim claim : theirClaims) {
163	            logs.findByClaimIdOrderByIdAsc(claim.getId()).stream()
164	                    .filter(line -> line.getStatus() == ClaimStatus.OPEN).map(ClaimLogEntry::getOn).findFirst()
165	                    .ifPresent(on -> openedOn.put(claim.getId(), on));
166	        }
167	        List<Claim> numbered = theirClaims.stream().filter(claim -> claim.getNumber() != null)
168	                .sorted(Comparator.comparing((Claim claim) -> openedOn.getOrDefault(claim.getId(), LocalDate.MAX))
169	                        .thenComparing(Claim::getId))
170	                .toList();
171	        Map<String, String> oldNumbers = new HashMap<>();
172	        numbered.forEach(claim -> oldNumbers.put(String.valueOf(claim.getId()), claim.getNumber()));
173	        List<String> tags = Stream.concat(person.getTags().stream(),
174	                theirClaims.stream().flatMap(claim -> claim.getTags().stream())).distinct().toList();
175	        LocalDate today = sheets.today(to);
176	        Long personId = person.getId();
177	        entities.flush();
178	
179	        // Left behind on this sheet: patron links both ways, pool and crew memberships, holds, watches,
180	        // and the claims' comments.
181	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", personId, personId);
182	        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", personId);
183	        jdbc.update("DELETE FROM crew_member WHERE person_id = ?", personId);
184	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", personId);
185	        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", personId);
186	        jdbc.update("DELETE FROM claim_comment WHERE claim_id IN (SELECT id FROM claim WHERE person_id = ?)",
187	                personId);
188	
189	        // Carried to the other sheet: the person, their grades, aliases, statements and claims with
190	        // their logs and the figures a statement bound.
191	        // One to be merged stays a person of this sheet, merged and gone from it, so their name does not
192	        // meet the one they are merged into on the other sheet.
193	        if (intoId == null) {
194	            jdbc.update("UPDATE person SET sheet_id = ?, added_on = ?, origin_sheet_id = ? WHERE id = ?", to, today,
195	                    sheetId, personId);
196	        }
197	        jdbc.update("UPDATE person_grade SET sheet_id = ? WHERE person_id = ?", to, personId);
198	        jdbc.update("UPDATE person_terms SET sheet_id = ? WHERE person_id = ?", to, personId);
199	        jdbc.update("UPDATE person_alias SET sheet_id = ? WHERE person_id = ?", to, personId);
200	        jdbc.update("UPDATE statement SET sheet_id = ? WHERE person_id = ?", to, personId);
201	        jdbc.update("UPDATE claim SET sheet_id = ?, claim_number = NULL, ref = NULL, ref_key = NULL,"
202	                + " settle_batch = NULL, locked_by = NULL WHERE person_id = ?", to, personId);
203	        jdbc.update("UPDATE claim_status_log SET sheet_id = ? WHERE claim_id IN (SELECT id FROM claim WHERE"
204	                + " person_id = ?)", to, personId);
205	        entities.clear();
206	
207	        Map<String, String> newNumbers = new HashMap<>();
208	        for (Claim was : numbered) {
209	            Claim claim = claims.findById(was.getId()).orElseThrow();
210	            String number = claimService.numberFor(to, claim.getDueBy());
211	            newNumbers.put(oldNumbers.get(String.valueOf(claim.getId())), number);
212	            claim.setNumber(number);
213	            claims.saveAndFlush(claim);
214	        }
215	        for (Claim was : theirClaims) {
216	            Claim claim = claims.findById(was.getId()).orElseThrow();
217	            if (claim.getCorrects() != null) {
218	                claim.setCorrects(newNumbers.get(claim.getCorrects()));
219	                claims.saveAndFlush(claim);
220	            }
221	            if (claim.getSplitFrom() != null) {
222	                jdbc.update("UPDATE claim SET split_from = ? WHERE id = ?", newNumbers.get(claim.getSplitFrom()),
223	                        claim.getId());
224	            }
225	            history.claimKept(claim.getId());
226	        }
227	        history.personKept(personId);
228	        tags.forEach(tag -> claims.useTag(to, tag));
229	        entities.clear();
230	
231	        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
232	                + " to=" + to);
233	        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + to + " by=" + user + " name=" + person.getName()
234	                + " from=" + sheetId);
235	        if (intoId != null) {
236	            merges.absorb(to, user, people.findById(personId).orElseThrow(), people.findById(intoId).orElseThrow());
237	        }
238	    }
239	}
