12	/** The grades given to the people on a sheet, each in force from its from-date. */
13	@Service
14	public class PersonGradeService {
15	
16	    /** Grades from the earliest: no from-date first, then by from-date. */
17	    private static final Comparator<PersonGrade> FROM_EARLIEST =
18	            Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()));
19	
20	    private final PersonGradeRepository grades;
21	    private final History history;
22	
23	    public PersonGradeService(PersonGradeRepository grades, History history) {
24	        this.grades = grades;
25	        this.history = history;
26	    }
27	
28	    /** A person's grades, from the earliest. */
29	    public List<PersonGrade> of(Long personId) {
30	        return grades.findByPersonId(personId).stream().sorted(FROM_EARLIEST).toList();
31	    }
32	
33	    /** Each person's grades on the sheet, from the earliest, by person id. */
34	    public Map<Long, List<PersonGrade>> bySheet(String sheetId) {
35	        return grades.findBySheetId(sheetId).stream().sorted(FROM_EARLIEST)
36	                .collect(Collectors.groupingBy(PersonGrade::getPersonId));
37	    }
38	
39	    /** Each person's grades on the sheet as they stood at the end of a day, from the earliest, by
40	     *  person id (null: as they stand now). */
41	    public Map<Long, List<PersonGrade>> bySheet(String sheetId, LocalDate asOf) {
42	        if (asOf == null) {
43	            return bySheet(sheetId);
44	        }
45	        return bySheet(sheetId).keySet().stream().collect(Collectors.toMap(id -> id,
46	                id -> history.grades(id, asOf).stream().sorted(FROM_EARLIEST).toList()));
47	    }
48	
49	    /** The person's grade in force on a date: the one whose from-date is the latest on or before it
50	     *  (the first grade applies from the beginning of time). */
51	    public String gradeOn(Long personId, LocalDate date) {
52	        return gradeOn(of(personId), date);
53	    }
54	
55	    /** The person's grade in force on a date as their grades stood at the end of a day (null: as
56	     *  they stand now). */
57	    public String gradeOn(Long personId, LocalDate date, LocalDate asOf) {
58	        return gradeOn(asOf == null ? of(personId) : history.grades(personId, asOf), date);
59	    }
60	
61	    /** The grade in force on a date among a person's grades; null when they have none. */
62	    public static String gradeOn(List<PersonGrade> theirs, LocalDate date) {
63	        return theirs.stream()
64	                .filter(g -> g.appliesOn(date))
65	                .max(FROM_EARLIEST)
66	                .map(PersonGrade::getGrade)
67	                .orElse(null);
68	    }
69	
70	    /** Give a person a grade from a date (null: from the beginning of time), replacing the one they
71	     *  had from that date and keeping the others. */
72	    public PersonGrade give(Person person, String grade, LocalDate from) {
73	        Optional<PersonGrade> had = from == null
74	                ? grades.findByPersonIdAndFromIsNull(person.getId())
75	                : grades.findByPersonIdAndFrom(person.getId(), from);
76	        PersonGrade given = had
77	                .map(existing -> {
78	                    existing.setGrade(grade);
79	                    return existing;
80	                })
81	                .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), grade, from));
82	        return grades.saveAndFlush(given);
83	    }
84	
85	    /** Make every grade a person was given of one grade the other, whatever its from-date. */
86	    public void regrade(Long personId, String from, String into) {
87	        grades.findByPersonId(personId).stream()
88	                .filter(g -> from.equals(g.getGrade()))
89	                .forEach(g -> {
90	                    g.setGrade(into);
91	                    grades.saveAndFlush(g);
92	                });
93	    }
94	}
