32	     *  optional to-date exactly as the row's hold would, each followed by the figures it moved. Refused
33	     *  as a whole, writing nothing, when any selected person is not on the sheet or the to-date is before
34	     *  the from-date. A viewer, or anyone on an archived sheet, holds no one. */
35	    @Transactional
36	    public List<Person> hold(String sheetId, String user, Set<Long> ids, LocalDate from, LocalDate to) {
37	        List<Person> selected = service.list(sheetId).stream()
38	                .filter(person -> ids.contains(person.getId())).toList();
39	        if (selected.size() != ids.size()) {
40	            throw new NoSuchElementException("Not every selected person is on sheet " + sheetId);
41	        }
42	        List<Person> held = new ArrayList<>();
43	        if (settings.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
44	            // A viewer, or anyone on an archived sheet, changes nothing: no selected person is held.
45	            return held;
46	        }
47	        for (Person person : selected) {
