 12	
 13	    /** The sheet's people in list order (by position); a person merged into another has left it. */
 14	    @Query("select p from Person p where p.sheetId = :sheetId and p.mergedInto is null order by p.position, p.id")
 15	    List<Person> findBySheetIdOrderByIdAsc(String sheetId);
 16	
 17	    /** Everyone ever added to the sheet in list order (by position), those since merged into another
 18	     *  included: a past day's view shows the people who were on the sheet then. */
 19	    @Query("select p from Person p where p.sheetId = :sheetId order by p.position, p.id")
 20	    List<Person> findEverBySheetId(String sheetId);
 21	
 22	    /** The person on the sheet; a person merged into another has left it. */
 23	    @Query("select p from Person p where p.id = :id and p.sheetId = :sheetId and p.mergedInto is null")
 24	    Optional<Person> findByIdAndSheetId(Long id, String sheetId);
 25	
 26	    /** The sheet's person with this name or alias, ignoring case; a person merged into another has left it. */
 27	    @Query("select p from Person p where p.sheetId = :sheetId and p.mergedInto is null and (lower(p.name) = lower(:name)"
 28	            + " or exists (select a from PersonAlias a where a.personId = p.id and a.aliasKey = lower(:name)))")
 29	    Optional<Person> findByName(String sheetId, String name);
 30	
 31	    /** Whether another person on the sheet (not {@code exceptId}) has this name, ignoring case. */
 32	    @Query("select count(p) > 0 from Person p where p.sheetId = :sheetId and lower(p.name) = lower(:name)"
 33	            + " and (:exceptId is null or p.id <> :exceptId)")
 34	    boolean nameInUse(String sheetId, String name, Long exceptId);
 35	
 36	    /** Whether anyone on any of the sheets has this name, ignoring case. */
 37	    @Query("select count(p) > 0 from Person p where p.sheetId in :sheetIds and lower(p.name) = lower(:name)")
 38	    boolean nameInUseOn(Collection<String> sheetIds, String name);
 39	
 40	    /** The names on any of the sheets, lower-cased. */
 41	    @Query("select lower(p.name) from Person p where p.sheetId in :sheetIds")
 42	    List<String> nameKeysOn(Collection<String> sheetIds);
 43	
 44	    /** Whether another person on the sheet (not {@code exceptId}) has this contact. */
 45	    @Query("select count(p) > 0 from Person p where p.sheetId = :sheetId and p.contact = :contact"
 46	            + " and (:exceptId is null or p.id <> :exceptId)")
 47	    boolean contactInUse(String sheetId, String contact, Long exceptId);
 48	
 49	    /** Put a person at the end of the list, as though just added. */
 50	    @Modifying(flushAutomatically = true, clearAutomatically = true)
 51	    @Query(value = "UPDATE person SET list_position = NEXT VALUE FOR person_position_seq WHERE id = :id",
 52	            nativeQuery = true)
 53	    void toEnd(@Param("id") Long id);
