115	/** Merges one grade into another: everyone on the merged grade today is given the other, and every
116	 *  grade of theirs on the merged grade, whatever its from-date, becomes the other. */
117	@Service
118	public class GradeMergeService {
119	
120	    private final PersonRepository people;
121	    private final PersonService service;
122	    private final PersonGradeService grades;
123	    private final GradeService gradeRules;
124	    private final RollupService rollups;
125	    private final SettingService settings;
126	    private final SheetService sheets;
127	    private final Audit audit;
128	
129	    public GradeMergeService(PersonRepository people, PersonService service, PersonGradeService grades,
130	            GradeService gradeRules, RollupService rollups, SettingService settings, SheetService sheets, Audit audit) {
131	        this.people = people;
132	        this.service = service;
133	        this.grades = grades;
134	        this.gradeRules = gradeRules;
135	        this.rollups = rollups;
136	        this.settings = settings;
137	        this.sheets = sheets;
138	        this.audit = audit;
139	    }
140	
141	    /** A steward merges a grade into another: every person whose grade in force on the sheet's today
142	     *  is the merged grade is given the other from the sheet's today, in list order, exactly as saving
143	     *  them from the editor with their name and terms unchanged would, each followed by the figures it
144	     *  moved; then every grade record of theirs on the merged grade becomes the other, so all their
145	     *  claims, whatever their date, use the other grade, and the merge as a whole is followed by the
146	     *  figures it moved. Anyone but a steward, the same grade twice, or a grade that is not one, is refused, as is
147	     *  the merge as a whole when any person cannot be given the grade (a retired one). Returns the
148	     *  people given the grade, in that order. */
149	    @Transactional
150	    public List<Person> merge(String sheetId, String user, String from, String into) {
151	        if (!gradeRules.isGrade(sheetId, from) || !gradeRules.isGrade(sheetId, into)) {
152	            throw new GradeMergeRefusedException("There is no grade " + from + " or " + into);
153	        }
154	        if (from.equals(into)) {
155	            throw new GradeMergeRefusedException("A grade cannot be merged into itself");
156	        }
157	        sheets.lock(sheetId);
158	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
159	            throw new GradeMergeRefusedException(user + " is not a steward: only a steward merges grades");
160	        }
161	        audit.recordOnCommit("GRADE_MERGED sheet=" + sheetId + " by=" + user + " from=" + from + " into=" + into);
162	        LocalDate today = sheets.today(sheetId);
163	        return rollups.track(sheetId, user, () -> {
164	            List<Person> merged = new ArrayList<>();
165	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
166	                if (!from.equals(grades.gradeOn(person.getId(), today))) {
167	                    continue;
168	                }
169	                merged.add(rollups.track(sheetId, user, () -> service.update(sheetId, user, person.getId(),
170	                        person.getVersion(), person.getName(), into, today, service.termsOn(person, today),
171	                        person.getContact())));
172	            }
173	            merged.forEach(person -> grades.regrade(person.getId(), from, into));
174	            return merged;
175	        });
176	    }
177	}
