 16	/** The holidays on a sheet: days a claim's due-by, fixed when the claim is added, does not count
 17	 *  among the business days of its terms. */
 18	@Service
 19	public class HolidayService {
 20	
 21	    private final HolidayRepository holidays;
 22	    private final ClaimRepository claims;
 23	    private final SheetService sheets;
 24	    private final Audit audit;
 25	
 26	    public HolidayService(HolidayRepository holidays, ClaimRepository claims, SheetService sheets, Audit audit) {
 27	        this.holidays = holidays;
 28	        this.claims = claims;
 29	        this.sheets = sheets;
 30	        this.audit = audit;
 31	    }
 32	
 33	    /** The sheet's holidays, the earliest first. */
 34	    public List<Holiday> list(String sheetId) {
 35	        return holidays.findBySheetIdOrderByDateAsc(sheetId);
 36	    }
 37	
 38	    /** Add a holiday to the sheet. Refused when the date is already on its list. The sheet is held
 39	     *  locked so the same date added at the same moment is checked against itself. Every claim on the
 40	     *  sheet that is not SETTLED or VOID, is due by the holiday or later and whose due-by a steward did not
 41	     *  set directly has its due-by re-fixed:
 42	     *  worked out again from its date, with the terms it was fixed with, over the holidays now on the
 43	     *  sheet. */
 44	    @Transactional
 45	    public Holiday add(String sheetId, String user, LocalDate date) {
 46	        sheets.lock(sheetId);
 47	        if (holidays.existsBySheetIdAndDate(sheetId, date)) {
 48	            throw new HolidayRefusedException("The date " + date + " is already a holiday on the sheet");
 49	        }
 50	        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
 51	        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDate).collect(Collectors.toSet());
 52	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
 53	            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
 54	                    || claim.isDueBySet() || claim.getDueBy().isBefore(date)) {
 55	                continue;
 56	            }
 57	            LocalDate dueBy = businessDaysAfter(days, claim.getDate(), claim.getTerms());
 58	            if (!dueBy.equals(claim.getDueBy())) {
 59	                claim.refix(dueBy);
 60	                claims.saveAndFlush(claim);
 61	            }
 62	        }
 63	        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + date);
 64	        return saved;
 65	    }
 66	
 67	    /** The terms-th business day after a date: counting forward from the day after it, skipping
 68	     *  every Saturday, Sunday and holiday on the sheet now. With no terms, the date itself when it
 69	     *  is a business day, else the next one. */
 70	    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int terms) {
 71	        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDate).collect(Collectors.toSet());
 72	        return businessDaysAfter(days, date, terms);
 73	    }
 74	
 75	    /** The terms-th business day after a date, skipping weekends and the given holidays. */
 76	    public static LocalDate businessDaysAfter(Set<LocalDate> holidays, LocalDate date, int terms) {
 77	        LocalDate day = date;
 78	        if (terms <= 0) {
 79	            while (!isBusinessDay(holidays, day)) {
 80	                day = day.plusDays(1);
 81	            }
 82	            return day;
 83	        }
 84	        for (int counted = 0; counted < terms; ) {
 85	            day = day.plusDays(1);
 86	            if (isBusinessDay(holidays, day)) {
 87	                counted++;
 88	            }
 89	        }
 90	        return day;
 91	    }
 92	
 93	    private static boolean isBusinessDay(Set<LocalDate> holidays, LocalDate day) {
 94	        DayOfWeek dow = day.getDayOfWeek();
 95	        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
 96	    }
 97	}
