196	     *  (the other leaving those crews' members), and their memberships become the other's, dropped
197	     *  where the other leads the crew or is in it already. */
198	    @Transactional
199	    public void merge(Long fromId, Long intoId) {
200	        for (Crew crew : crews.findByLeadIdOrderByIdAsc(fromId)) {
201	            crew.setLeadId(intoId);
202	            crews.saveAndFlush(crew);
203	            members.findByPersonIdOrderByIdAsc(intoId).stream().filter(m -> m.getCrewId().equals(crew.getId()))
204	                    .forEach(members::delete);
205	            members.flush();
206	        }
207	        for (CrewMember member : members.findByPersonIdOrderByIdAsc(fromId)) {
208	            Crew crew = crews.findById(member.getCrewId()).orElseThrow();
209	            if (crew.getLeadId().equals(intoId) || members.existsByCrewIdAndPersonId(crew.getId(), intoId)) {
210	                members.delete(member);
211	                members.flush();
212	            } else {
213	                member.setPersonId(intoId);
214	                members.saveAndFlush(member);
215	            }
