415	    93	    /** Take a statement for a person now, or as of a day on or before the sheet's today (null: now):
416	    94	     *  their claims, newest first, as bound by it. Taken as of a day, it binds their claims that
417	    95	     *  counted at the end of it to their figures as they stood then (every change made while the
418	    96	     *  sheet's today was on or before it counts, every later one does not), that day standing in for
419	    97	     *  the sheet's today in every figure; it is dated that day. A day after the sheet's today, or
420	    98	     *  before the person was on the sheet, is refused. */
421	    99	    @Transactional
422	   100	    public List<Claim> take(String sheetId, String user, Long personId, LocalDate asOf) {
423	   101	        // Lock the sheet, so a claim changed or a statement taken at the same moment waits.
424	   102	        sheets.lock(sheetId);
425	   103	        Person person = people.findByIdAndSheetId(personId, sheetId)
426	   104	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
427	   105	        LocalDate today = sheets.today(sheetId);
428	   106	        if (asOf != null && asOf.isAfter(today)) {
429	   107	            throw new StatementRefusedException("A statement is taken as of a day on or before the sheet's today " + today);
430	   108	        }
431	   109	        if (asOf != null && !person.onSheetAsOf(asOf)) {
432	   110	            throw new StatementRefusedException(person.getName() + " was not on the sheet on " + asOf);
433	   111	        }
434	   112	        LocalDate day = asOf != null ? asOf : today;
435	   113	        // What the shares of claims move in their due-total, as their row shows it.
436	   114	        BigDecimal sharedPart = rollups.sharedPartOf(sheetId, personId, asOf);
437	   115	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
438	   116	        BigDecimal total = BigDecimal.ZERO.setScale(2);
439	   117	        boolean anyFigure = false;
440	   118	        int counted = 0;
441	   119	        LocalDate latest = null;
442	   120	        for (Claim claim : theirs) {
443	   121	            // The claim as it stood at the end of the day; one not yet theirs then is left out.
444	   122	            Claim then = asOf == null ? claim
445	   123	                    : history.claim(claim.getId(), asOf).filter(was -> was.getPersonId().equals(personId)).orElse(null);
446	   124	            // A deferred claim is left out of the statement (one an earlier statement bound is not deferred: it
447	   125	            // stays in); one left out for the retirement of its person is left out unless an earlier one bound it.
448	   126	            if (then == null || !then.counts() || then.deferredOn(day)
449	   127	                    || (!then.isStated() && then.retiredOn(person.getRetiredFrom(), day))) {
450	   128	                claim.unbind();
451	   129	                continue;
452	   130	            }
453	   131	            // The statement binds the due as shown, late charge included: one an earlier statement bound
454	   132	            // stays as it is.
455	   133	            BigDecimal due = claimService.dueOf(sheetId, person, then, asOf);
456	   134	            if (due != null) {
457	   135	                total = total.add(due);
458	   136	                anyFigure = true;
459	   137	            }
460	   138	            claim.bind(due);
461	   139	            counted++;
462	   140	            if (latest == null || then.getDate().isAfter(latest)) {
463	   141	                latest = then.getDate();
464	   142	            }
465	   143	        }
466	   144	        if (sharedPart != null) {
467	   145	            total = total.add(sharedPart);
468	   146	            anyFigure = true;
469	   147	        }
470	   148	        claims.saveAllAndFlush(theirs);
471	   149	        boolean hasRate = rates.rateOn(sheetId, grades.gradeOn(person.getId(), day, asOf), day, asOf).isPresent();
472	   150	        BigDecimal cutTotal = cuts.cutTotals(sheetId, asOf, personService.list(sheetId, asOf))
473	   151	                .getOrDefault(personId, BigDecimal.ZERO.setScale(2));
474	   152	        String dueTotal = hasRate || anyFigure ? settings.capped(sheetId, total, cutTotal, latest, asOf).toPlainString()
475	   153	                : NO_RATE;
476	   154	        statements.saveAndFlush(new Statement(sheetId, personId, day, dueTotal, counted, today));
477	   155	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
478	   156	                + " due-total=" + dueTotal + " claims=" + counted + (asOf != null ? " asof=" + asOf : ""));
479	   157	        return theirs;
480	   158	    }
