482	   160	    /** A steward cancels a person's last statement: the claims it bound become live again (a figure
483	   161	     *  bound by an earlier statement is not restored) and it is no longer counted, though the sheet as it
484	   162	     *  stood at the end of a day before it was cancelled still shows it. Anyone else, or a
485	   163	     *  person with no statement, is refused. Returns their claims, newest first. */
486	   164	    @Transactional
487	   165	    public List<Claim> cancel(String sheetId, String user, Long personId) {
488	   166	        sheets.lock(sheetId);
489	   167	        Person person = people.findByIdAndSheetId(personId, sheetId)
490	   168	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
491	   169	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
492	   170	            throw new StatementCancelRefusedException(user + " is not a steward: only a steward cancels a statement");
493	   171	        }
494	   172	        List<Statement> theirs = statements.inOrder(sheetId, personId).stream()
495	   173	                .filter(Statement::isLive).toList();
496	   174	        if (theirs.isEmpty()) {
497	   175	            throw new StatementCancelRefusedException(person.getName() + " has no statement to cancel");
498	   176	        }
499	   177	        Statement last = theirs.get(theirs.size() - 1);
500	   178	        List<Claim> theirClaims = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
501	   179	        List<Claim> bound = theirClaims.stream().filter(Claim::isStated).toList();
502	   180	        bound.forEach(Claim::unbind);
503	   181	        claims.saveAllAndFlush(bound);
504	   182	        // Kept, marked cancelled, so the sheet as it stood at the end of an earlier day still shows it.
505	   183	        last.cancel(sheets.today(sheetId));
506	   184	        statements.saveAndFlush(last);
507	   185	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
508	   186	                + " due-total=" + last.getDueTotal());
509	   187	        return theirClaims;
510	   188	    }
