 23	/** The pools on a sheet: each a name and its members, people or other pools of the sheet, each with a
 24	 *  share percent. */
 25	@Service
 26	public class PoolService {
 27	
 28	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
 29	
 30	    /** The most pools a chain of pools, each a member of the one above, may hold. */
 31	    private static final int MAX_DEPTH = 3;
 32	
 33	    /** A pool with its members, in the order they were added. */
 34	    public record PoolWithMembers(Pool pool, List<PoolMember> members) {
 35	    }
 36	
 37	    /** A crew as a pool: its name, and its lead's then its members' person ids, in the order they were
 38	     *  added, each with its share, in the same order. */
 39	    public record CrewPool(Crew crew, List<Long> personIds, List<BigDecimal> shares) {
 40	    }
 41	
 42	    private final PoolRepository pools;
 43	    private final PoolMemberRepository members;
 44	    private final PersonRepository people;
 45	    private final CrewRepository crews;
 46	    private final CrewMemberRepository crewMembers;
 47	    private final SheetService sheets;
 48	    private final Audit audit;
 49	
 50	    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
 51	            CrewRepository crews, CrewMemberRepository crewMembers, SheetService sheets, Audit audit) {
 52	        this.pools = pools;
 53	        this.members = members;
 54	        this.people = people;
 55	        this.crews = crews;
 56	        this.crewMembers = crewMembers;
 57	        this.sheets = sheets;
 58	        this.audit = audit;
 59	    }
