 66	    /** The sheet's pools as they stood at the end of a day (null: as they stand now), in the order
 67	     *  they were added, each with its members added by then. */
 68	    public List<PoolWithMembers> list(String sheetId, LocalDate day) {
 69	        List<Pool> list = pools.findBySheetIdOrderByIdAsc(sheetId).stream()
 70	                .filter(p -> day == null || p.madeAsOf(day)).toList();
 71	        Map<Long, List<PoolMember>> byPool = members
 72	                .findByPoolIdInOrderByIdAsc(list.stream().map(Pool::getId).toList()).stream()
 73	                .filter(m -> day == null || m.madeAsOf(day))
 74	                .collect(Collectors.groupingBy(PoolMember::getPoolId));
 75	        return list.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
 76	    }
 77	
 78	    /** The sheet's crews as pools, in the order they were added: each the lead and the members at equal
 79	     *  shares, 100.00 split as patrons' shares are (each rounded half to even), the remainder on the first.
 80	     *  A lead who has left the sheet (transferred or merged away) is not among them. */
 81	    public List<CrewPool> crewPools(String sheetId) {
 82	        return crewPools(sheetId, null);
 83	    }
