 85	    /** The sheet's crews as pools as they stood at the end of a day (null: as they stand now): those
 86	     *  added by then, each with its members added by then. */
 87	    public List<CrewPool> crewPools(String sheetId, LocalDate day) {
 88	        List<Crew> list = crews.findBySheetIdOrderByIdAsc(sheetId).stream()
 89	                .filter(c -> day == null || c.madeAsOf(day)).toList();
 90	        Map<Long, List<CrewMember>> byCrew = crewMembers
 91	                .findByCrewIdInOrderByIdAsc(list.stream().map(Crew::getId).toList()).stream()
 92	                .filter(m -> day == null || m.madeAsOf(day))
 93	                .collect(Collectors.groupingBy(CrewMember::getCrewId));
 94	        Set<Long> onSheet = people.findBySheetIdOrderByIdAsc(sheetId).stream().map(Person::getId)
 95	                .collect(Collectors.toSet());
 96	        return list.stream().map(crew -> {
 97	            List<Long> ids = new ArrayList<>();
 98	            ids.add(crew.getLeadId());
 99	            byCrew.getOrDefault(crew.getId(), List.of()).forEach(m -> ids.add(m.getPersonId()));
100	            ids.removeIf(id -> !onSheet.contains(id));
101	            return new CrewPool(crew, ids, equalShares(ids.size()));
102	        }).toList();
103	    }
104	
105	    /** 100.00 split equally over this many, each rounded half to even, the remainder on the first; none for none. */
106	    private static List<BigDecimal> equalShares(int count) {
107	        if (count == 0) {
108	            return List.of();
109	        }
110	        BigDecimal each = HUNDRED.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_EVEN);
111	        List<BigDecimal> shares = new ArrayList<>();
112	        for (int i = 0; i < count; i++) {
113	            shares.add(each);
114	        }
115	        shares.set(0, each.add(HUNDRED.subtract(each.multiply(BigDecimal.valueOf(count)))));
116	        return shares;
117	    }
