119	    /** Add a pool, its name trimmed. Refused when the name is blank or already a pool's or a crew's on the sheet.
120	     *  The sheet is held locked so the same name added at the same moment is checked against itself. */
121	    @Transactional
122	    public PoolWithMembers add(String sheetId, String user, String name) {
123	        String key = name == null ? "" : name.trim();
124	        if (key.isEmpty()) {
125	            throw new PoolRefusedException("A pool needs a name");
126	        }
127	        sheets.lock(sheetId);
128	        if (pools.existsBySheetIdAndName(sheetId, key)) {
129	            throw new PoolRefusedException("The pool " + key + " is on the sheet already");
130	        }
131	        if (crews.existsBySheetIdAndName(sheetId, key)) {
132	            throw new PoolRefusedException("The crew " + key + " is a pool on the sheet already");
133	        }
134	        Pool saved = pools.saveAndFlush(new Pool(sheetId, key).madeOn(sheets.today(sheetId)));
135	        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + key);
136	        return new PoolWithMembers(saved, List.of());
137	    }
138	
139	    /** Add a member to a pool with a share percent: more than 0.00 and at most 100.00, with up to two
140	     *  decimals, and an optional from-date and to-date, both included. The member is a person of the
141	     *  sheet, or another pool of the sheet (memberPoolId). Refused for such a share, a to-date before
142	     *  the from-date, a person already in the pool, a pool that is a member of a pool
143	     *  already, a pool that would contain itself through any chain, or a chain of pools more than
144	     *  three deep. */
145	    @Transactional
146	    public PoolWithMembers addMember(String sheetId, String user, Long poolId, Long personId, Long memberPoolId,
147	            BigDecimal share, LocalDate from, LocalDate to) {
148	        if (from != null && to != null && to.isBefore(from)) {
149	            throw new PoolRefusedException("A membership's to-date is not before its from-date");
150	        }
151	        if (share == null || share.signum() <= 0 || share.compareTo(HUNDRED) > 0
152	                || share.stripTrailingZeros().scale() > 2) {
153	            throw new PoolRefusedException("A share is more than 0.00 and at most 100.00, with two decimals");
154	        }
155	        if ((personId == null) == (memberPoolId == null)) {
156	            throw new PoolRefusedException("A member is a person or a pool");
157	        }
158	        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
159	        sheets.lock(sheetId);
160	        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
161	                .orElseThrow(() -> new PoolRefusedException("No such pool on the sheet"));
162	        String name;
163	        if (personId != null) {
164	            Person person = people.findByIdAndSheetId(personId, sheetId)
165	                    .orElseThrow(() -> new PoolRefusedException("No such person on the sheet"));
166	            if (members.existsByPoolIdAndPersonId(poolId, personId)) {
167	                throw new PoolRefusedException(person.getName() + " is in the pool " + pool.getName() + " already");
168	            }
169	            members.saveAndFlush(
170	                    new PoolMember(poolId, personId, scaled).dated(from, to).madeOn(sheets.today(sheetId)));
171	            name = person.getName();
172	        } else {
173	            Pool member = pools.findByIdAndSheetId(memberPoolId, sheetId)
174	                    .orElseThrow(() -> new PoolRefusedException("No such pool on the sheet"));
175	            checkNesting(sheetId, pool, member);
176	            members.saveAndFlush(
177	                    PoolMember.ofPool(poolId, memberPoolId, scaled).dated(from, to).madeOn(sheets.today(sheetId)));
178	            name = member.getName();
179	        }
180	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
181	                + " name=" + name + " share=" + scaled.toPlainString() + (from != null ? " from=" + from : "")
182	                + (to != null ? " to=" + to : ""));
183	        return new PoolWithMembers(pool, members.findByPoolIdInOrderByIdAsc(List.of(poolId)));
184	    }
185	
186	    /** Refuse making the pool member a member of the pool when it is a member of a pool already, when
187	     *  the pool is the member or lies inside it, or when the chain of pools would be more than three
188	     *  deep. */
189	    private void checkNesting(String sheetId, Pool pool, Pool member) {
190	        if (members.findByMemberPoolId(member.getId()).isPresent()) {
191	            throw new PoolRefusedException("The pool " + member.getName() + " is a member of a pool already");
192	        }
193	        Map<Long, Long> parentOf = new HashMap<>();
194	        Map<Long, List<Long>> childrenOf = new HashMap<>();
195	        List<Long> ids = pools.findBySheetIdOrderByIdAsc(sheetId).stream().map(Pool::getId).toList();
196	        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(ids)) {
197	            if (m.getMemberPoolId() != null) {
198	                parentOf.put(m.getMemberPoolId(), m.getPoolId());
199	                childrenOf.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
200	            }
201	        }
202	        // The pools from the pool up to the top, the pool counted.
203	        int above = 0;
204	        for (Long at = pool.getId(); at != null; at = parentOf.get(at)) {
205	            if (at.equals(member.getId())) {
206	                throw new PoolRefusedException("The pool " + pool.getName() + " would contain itself");
207	            }
208	            above++;
209	        }
210	        if (above + height(member.getId(), childrenOf) > MAX_DEPTH) {
211	            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep");
212	        }
213	    }
214	
215	    /** The pools in the longest chain down from this pool, the pool counted. */
216	    private int height(Long poolId, Map<Long, List<Long>> childrenOf) {
217	        int below = 0;
218	        for (Long child : childrenOf.getOrDefault(poolId, List.of())) {
219	            below = Math.max(below, height(child, childrenOf));
220	        }
221	        return below + 1;
222	    }
