243	/** Each person's cut total: their cuts of the pot across every pool they are a member of, worked out
244	 *  as the screen shows them. */
245	@Service
246	public class PoolCutService {
247	
248	    private static final BigDecimal NONE = BigDecimal.ZERO.setScale(2);
249	
250	    private static final BigDecimal FULL = new BigDecimal("100.00");
251	
252	    /** A member: a person or a pool, its share and its dates (null: no bound). */
253	    private record Member(Long personId, Long memberPoolId, BigDecimal share, LocalDate from, LocalDate to) {
254	    }
255	
256	    /** A pool, or a crew as one (its id negated), with its members in the order they were added. */
257	    private record CutPool(Long id, List<Member> members) {
258	    }
259	
260	    /** A member's share, whether it is a retired person, a person with a hold in force on the day, and
261	     *  whether its dates leave it out on the day. */
262	    private record Share(BigDecimal share, boolean retired, boolean held, boolean out) {
263	        boolean cutting() {
264	            return !retired && !held && !out;
265	        }
266	    }
267	
268	    private final PoolService pools;
269	    private final PersonService personService;
270	    private final SettingService settings;
271	    private final SheetService sheets;
272	
273	    public PoolCutService(PoolService pools, PersonService personService, SettingService settings,
274	            SheetService sheets) {
275	        this.pools = pools;
276	        this.personService = personService;
277	        this.settings = settings;
278	        this.sheets = sheets;
279	    }
280	
281	    /** Each person's cut total on the sheet as it stood at the end of a day, that day standing in for
282	     *  the sheet's today (null: as it shows them now), by person id; a person in no pool that shows cuts
283	     *  has 0.00. */
284	    public Map<Long, BigDecimal> cutTotals(String sheetId, LocalDate asOf, List<Person> sheetPeople) {
285	        LocalDate today = asOf != null ? asOf : sheets.today(sheetId);
286	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
287	        sheetPeople.forEach(person -> totals.put(person.getId(), NONE));
288	        BigDecimal pot = asOf != null ? settings.pot(sheetId, asOf) : settings.pot(sheetId);
289	        if (pot == null) {
290	            return totals;
291	        }
292	        List<CutPool> list = new ArrayList<>();
293	        pools.list(sheetId, asOf).forEach(p -> list.add(new CutPool(p.pool().getId(), p.members().stream()
294	                .map(m -> new Member(m.getPersonId(), m.getMemberPoolId(), m.getShare(), m.getFrom(), m.getTo()))
295	                .toList())));
296	        pools.crewPools(sheetId, asOf).forEach(c -> {
297	            List<Member> members = new ArrayList<>();
298	            for (int i = 0; i < c.personIds().size(); i++) {
299	                members.add(new Member(c.personIds().get(i), null, c.shares().get(i), null, null));
300	            }
301	            list.add(new CutPool(-c.crew().getId(), members));
302	        });
303	        Map<Long, Person> byId = new HashMap<>();
304	        sheetPeople.forEach(person -> byId.put(person.getId(), person));
305	        Map<Long, List<PersonHold>> holds = personService.holds(sheetId, asOf);
306	        Map<Long, CutPool> above = new HashMap<>();
307	        list.forEach(p -> p.members().forEach(m -> {
308	            if (m.memberPoolId() != null) {
309	                above.put(m.memberPoolId(), p);
310	            }
311	        }));
312	        for (CutPool pool : list) {
313	            List<BigDecimal> cut = cutsOf(pool, new HashSet<>(), above, byId, holds, pot, today);
314	            if (cut == null) {
315	                continue;
316	            }
317	            for (int i = 0; i < pool.members().size(); i++) {
318	                Long personId = pool.members().get(i).personId();
319	                if (personId != null && totals.containsKey(personId)) {
320	                    totals.merge(personId, cut.get(i), BigDecimal::add);
321	                }
322	            }
323	        }
324	        return totals;
325	    }
326	
327	    /** A pool's cuts, in its members' order; null when it is unbalanced, every member is retired or it
328	     *  has no pot: a pool that is a member of none has the sheet's pot, any other its cut in the pool above. */
329	    private List<BigDecimal> cutsOf(CutPool pool, Set<Long> seen, Map<Long, CutPool> above, Map<Long, Person> byId,
330	            Map<Long, List<PersonHold>> holds, BigDecimal pot, LocalDate today) {
331	        if (!seen.add(pool.id())) {
332	            return null;
333	        }
334	        List<Share> shares = pool.members().stream().map(m -> {
335	            Person person = m.personId() != null ? byId.get(m.personId()) : null;
336	            boolean retired = person != null && person.isRetired();
337	            boolean held = m.personId() != null
338	                    && holds.getOrDefault(m.personId(), List.of()).stream().anyMatch(h -> h.contains(today));
339	            boolean out = (m.from() != null && today.isBefore(m.from())) || (m.to() != null && m.to().isBefore(today));
340	            return new Share(m.share(), retired, held, out);
341	        }).toList();
342	        BigDecimal total = shares.stream().filter(s -> !s.out()).map(Share::share).reduce(NONE, BigDecimal::add);
343	        if (total.compareTo(FULL) != 0 || shares.stream().allMatch(Share::retired)) {
344	            return null;
345	        }
346	        CutPool parent = above.get(pool.id());
347	        BigDecimal from;
348	        if (parent != null) {
349	            List<BigDecimal> parentCuts = cutsOf(parent, new HashSet<>(seen), above, byId, holds, pot, today);
350	            int at = -1;
351	            for (int i = 0; i < parent.members().size(); i++) {
352	                if (pool.id().equals(parent.members().get(i).memberPoolId())) {
353	                    at = i;
354	                    break;
355	                }
356	            }
357	            from = parentCuts != null && at >= 0 ? parentCuts.get(at) : null;
358	        } else {
359	            from = pot;
360	        }
361	        return from == null ? null : cuts(from.setScale(2, RoundingMode.UNNECESSARY), shares);
362	    }
363	
364	    /** Each member's cut of the pot, in the members' order: one that is not cutting 0.00, its share spread
365	     *  over the others in proportion; any other's the pot times its share divided by the cutting shares
366	     *  added up, rounded half to even. The remainder goes to the member with the smallest non-zero cut,
367	     *  the latest added on a tie; with none, to the last cutting member. */
368	    private static List<BigDecimal> cuts(BigDecimal pot, List<Share> members) {
369	        BigDecimal shares = members.stream().filter(Share::cutting).map(Share::share).reduce(NONE, BigDecimal::add);
370	        List<BigDecimal> list = new ArrayList<>();
371	        if (shares.signum() == 0) {
372	            members.forEach(m -> list.add(NONE));
373	            return list;
374	        }
375	        for (Share m : members) {
376	            list.add(m.cutting() ? pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN) : NONE);
377	        }
378	        int smallest = -1;
379	        int last = -1;
380	        for (int i = 0; i < members.size(); i++) {
381	            if (!members.get(i).cutting()) {
382	                continue;
383	            }
384	            last = i;
385	            if (list.get(i).signum() != 0 && (smallest < 0 || list.get(i).compareTo(list.get(smallest)) <= 0)) {
386	                smallest = i;
387	            }
388	        }
389	        int taker = smallest >= 0 ? smallest : last;
390	        if (taker >= 0) {
391	            BigDecimal sum = list.stream().reduce(NONE, BigDecimal::add);
392	            list.set(taker, list.get(taker).add(pot.subtract(sum)));
393	        }
394	        return list;
395	    }
396	}
