 23	/** The plans on a sheet, and the generate that makes their claims. */
 24	@Service
 25	public class PlanService {
 26	
 27	    private final PlanRepository plans;
 28	    private final PlanClaimRepository made;
 29	    private final PlanPauseRepository pauses;
 30	    private final PlanChangeRepository changes;
 31	    private final PersonRepository people;
 32	    private final ClaimService claims;
 33	    private final SheetService sheets;
 34	    private final SettingService settings;
 35	    private final Audit audit;
 36	
 37	    public PlanService(PlanRepository plans, PlanClaimRepository made, PlanPauseRepository pauses,
 38	            PlanChangeRepository changes, PersonRepository people, ClaimService claims, SheetService sheets, SettingService settings, Audit audit) {
 39	        this.plans = plans;
 40	        this.made = made;
 41	        this.pauses = pauses;
 42	        this.changes = changes;
 43	        this.people = people;
 44	        this.claims = claims;
 45	        this.sheets = sheets;
 46	        this.settings = settings;
 47	        this.audit = audit;
 48	    }
 49	
 50	    /** The sheet's plans in the order they were added: as they stand now, or those added by the end
 51	     *  of the as-of date. */
 52	    public List<Plan> list(String sheetId, LocalDate asOf) {
 53	        return plans.findBySheetIdOrderByIdAsc(sheetId).stream()
 54	                .filter(p -> asOf == null || !p.getMadeOn().isAfter(asOf))
 55	                .toList();
 56	    }
 57	
 58	    /** How many claims each plan has made, by plan id: so far, or by the end of the as-of date. */
 59	    public Map<Long, Integer> generated(List<Plan> them, LocalDate asOf) {
 60	        Map<Long, Integer> counts = new HashMap<>();
 61	        for (PlanClaim c : made.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
 62	            if (asOf == null || !c.getMadeOn().isAfter(asOf)) {
 63	                counts.merge(c.getPlanId(), 1, Integer::sum);
 64	            }
 65	        }
 66	        return counts;
 67	    }
 68	
 69	    /** Each plan's pauses, by plan id: as they stand now, or as they stood at the end of the as-of
 70	     *  date (a pause made after it left out, one resumed after it still open). */
 71	    public Map<Long, List<PlanPause>> pauses(List<Plan> them, LocalDate asOf) {
 72	        Map<Long, List<PlanPause>> byPlan = new HashMap<>();
 73	        for (PlanPause p : pauses.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
 74	            if (asOf != null && p.getPausedOn().isAfter(asOf)) {
 75	                continue;
 76	            }
 77	            PlanPause shown = p;
 78	            if (asOf != null && p.getResumedOn() != null && p.getResumedOn().isAfter(asOf)) {
 79	                shown = new PlanPause(p.getPlanId(), p.getPausedOn());
 80	            }
 81	            byPlan.computeIfAbsent(p.getPlanId(), k -> new ArrayList<>()).add(shown);
 82	        }
 83	        return byPlan;
 84	    }
 85	
 86	    /** Each plan's amount changes, oldest first, by plan id: so far, or those made by the end of the
 87	     *  as-of date. */
 88	    public Map<Long, List<PlanChange>> changes(List<Plan> them, LocalDate asOf) {
 89	        Map<Long, List<PlanChange>> byPlan = new HashMap<>();
 90	        for (PlanChange c : changes.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
 91	            if (asOf == null || !c.getChangedOn().isAfter(asOf)) {
 92	                byPlan.computeIfAbsent(c.getPlanId(), k -> new ArrayList<>()).add(c);
 93	            }
 94	        }
 95	        return byPlan;
 96	    }
 97	
 98	    /** The plan's amount after its changes: that of the latest, or the one it was added with. */
 99	    public static BigDecimal amountAfter(Plan plan, List<PlanChange> them) {
100	        return them.isEmpty() ? plan.getAmount() : them.get(them.size() - 1).getAmount();
101	    }
102	
103	    /** Change the plan's amount on the sheet's today: an amount of 0.00 or more with up to two decimals.
104	     *  The claims it generates from then on take it, as do those it made already that are still DRAFT,
105	     *  each edited as the claim form would (on the sheet it was made on, passed over there when the user
106	     *  is a viewer or the form would refuse it); those in any other status keep theirs. */
107	    @Transactional
108	    public Plan changeAmount(String sheetId, String user, Long planId, String amount) {
109	        sheets.lock(sheetId);
110	        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
111	                .orElseThrow(() -> new NoSuchElementException("No plan " + planId + " on sheet " + sheetId));
112	        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow();
113	        BigDecimal figure = amountOf(amount);
114	        changes.saveAndFlush(new PlanChange(planId, sheets.today(sheetId), figure));
115	        audit.recordOnCommit("PLAN_CHANGED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
116	                + " start=" + plan.getStart() + " amount=" + figure.toPlainString());
117	        String on = plan.getTargetSheetId() != null ? plan.getTargetSheetId() : sheetId;
118	        if (!on.equals(sheetId)) {
119	            if (settings.isViewer(on, user)) {
120	                return plan;
121	            }
122	            sheets.lock(on);
123	        }
124	        for (PlanClaim c : made.findByPlanIdInOrderByIdAsc(List.of(planId))) {
125	            claims.updateAmount(on, user, c.getClaimId(), figure);
126	        }
127	        return plan;
128	    }
129	
130	    /** Whether the plan date falls in one of the pauses, and so is skipped. */
131	    public static boolean skipped(List<PlanPause> them, LocalDate date) {
132	        return them.stream().anyMatch(p -> p.skips(date));
133	    }
134	
135	    /** Pause the plan from the sheet's today, or resume it on the sheet's today; pausing a paused plan or
136	     *  resuming a running one is refused. */
137	    @Transactional
138	    public Plan pause(String sheetId, String user, Long planId, boolean on) {
139	        sheets.lock(sheetId);
140	        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
141	                .orElseThrow(() -> new NoSuchElementException("No plan " + planId + " on sheet " + sheetId));
142	        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow();
143	        LocalDate today = sheets.today(sheetId);
144	        Optional<PlanPause> open = pauses.findFirstByPlanIdAndResumedOnIsNull(planId);
145	        if (on) {
146	            if (open.isPresent()) {
147	                throw new PlanRefusedException("The plan is paused already");
148	            }
149	            pauses.saveAndFlush(new PlanPause(planId, today));
150	        } else {
151	            PlanPause pause = open.orElseThrow(() -> new PlanRefusedException("The plan is not paused"));
152	            pause.resume(today);
153	            pauses.saveAndFlush(pause);
154	        }
155	        audit.recordOnCommit((on ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + user
156	                + " name=" + person.getName() + " start=" + plan.getStart());
157	        return plan;
158	    }
159	
160	    /** Add a plan for a person: an amount of 0.00 or more with up to two decimals, a start (blank: the
161	     *  sheet's today), either every so many days (a whole number, at least 1) or monthly on a day of the
162	     *  month (1 to 31), and an end on or after the start. A sheet named (blank: none) must be one of the
163	     *  sheet's descendants: the plan then makes its claims there, for the person of the same name. */
164	    @Transactional
165	    public Plan add(String sheetId, String user, Long personId, String amount, LocalDate start, String every,
166	            String day, LocalDate end, String sheet) {
167	        Person person = people.findByIdAndSheetId(personId, sheetId)
168	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
169	        BigDecimal figure = amountOf(amount);
170	        boolean monthly = day != null && !day.isBlank();
171	        if (monthly && every != null && !every.isBlank()) {
172	            throw new PlanRefusedException("A plan runs either every so many days or on a day of the month");
173	        }
174	        Integer days = monthly ? null : everyOf(every);
175	        Integer dayOfMonth = monthly ? dayOf(day) : null;
176	        LocalDate today = sheets.today(sheetId);
177	        LocalDate from = start != null ? start : today;
178	        if (end == null || end.isBefore(from)) {
179	            throw new PlanRefusedException("A plan must end on or after its start");
180	        }
181	        String target = sheet == null || sheet.isBlank() ? null : sheet.trim();
182	        if (target != null && !sheets.descendants(sheetId).contains(target)) {
183	            throw new PlanRefusedException("The sheet " + target + " is not a descendant of this sheet");
184	        }
185	        Plan saved = plans.saveAndFlush(new Plan(sheetId, personId, figure, from, days, dayOfMonth, end, today,
186	                target));
187	        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
188	                + " amount=" + saved.getAmount().toPlainString() + " start=" + saved.getStart()
189	                + (monthly ? " day=" + saved.getDay() : " every=" + saved.getEvery()) + " end=" + saved.getEnd()
190	                + (target != null ? " sheet=" + target : ""));
191	        return saved;
192	    }
193	
194	    /** For every plan on the sheet, in the order they were added, add a DRAFT claim of its amount (that of its latest change, if any) with
195	     *  an empty note for each plan date up to its end and the sheet's today it has made none for yet,
196	     *  as the claim form would, a date a pause skips left out; a date the form refuses is passed over, to be tried again next time.
197	     *  A plan naming a descendant sheet makes its claims there instead, for the person of the same name
198	     *  on it (none when there is no such person, or the user is a viewer there), by that sheet's rules and in its audit.
199	     *  The claims made, in the order they were; a viewer makes none. */
200	    @Transactional
201	    public List<Claim> generate(String sheetId, String user) {
202	        if (settings.isViewer(sheetId, user)) {
203	            return List.of();
204	        }
205	        sheets.lock(sheetId);
206	        LocalDate today = sheets.today(sheetId);
207	        List<Plan> them = plans.findBySheetIdOrderByIdAsc(sheetId);
208	        Set<String> done = new HashSet<>();
209	        for (PlanClaim c : made.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
210	            done.add(c.getPlanId() + "@" + c.getDate());
211	        }
212	        Map<Long, List<PlanPause>> paused = pauses(them, null);
213	        Map<Long, List<PlanChange>> changed = changes(them, null);
214	        List<Claim> added = new ArrayList<>();
215	        Set<String> locked = new HashSet<>(Set.of(sheetId));
216	        for (Plan plan : them) {
217	            String on = plan.getTargetSheetId() != null ? plan.getTargetSheetId() : sheetId;
218	            Long personId = plan.getPersonId();
219	            if (!on.equals(sheetId)) {
220	                Optional<Person> own = people.findByIdAndSheetId(plan.getPersonId(), sheetId);
221	                Optional<Person> there = own.flatMap(p -> people.findByName(on, p.getName()));
222	                if (there.isEmpty() || settings.isViewer(on, user)) {
223	                    continue;
224	                }
225	                personId = there.get().getId();
226	                if (locked.add(on)) {
227	                    sheets.lock(on);
228	                }
229	            }
230	            List<PlanPause> its = paused.getOrDefault(plan.getId(), List.of());
231	            BigDecimal amount = amountAfter(plan, changed.getOrDefault(plan.getId(), List.of()));
232	            for (LocalDate date : plan.datesUpTo(today, d -> skipped(its, d))) {
233	                if (done.contains(plan.getId() + "@" + date) || !claims.accepts(on, personId, date)) {
234	                    continue;
235	                }
236	                Claim claim = claims.add(on, user, personId, amount, date, "", null);
237	                made.saveAndFlush(new PlanClaim(plan.getId(), date, claim.getId(), today));
238	                added.add(claim);
239	            }
240	        }
241	        return added;
242	    }
243	
244	    private static BigDecimal amountOf(String amount) {
245	        BigDecimal figure;
246	        try {
247	            figure = new BigDecimal(amount == null ? "" : amount.trim());
248	        } catch (NumberFormatException e) {
249	            throw new PlanRefusedException("The amount is not a number");
250	        }
251	        if (figure.signum() < 0 || figure.scale() > 2 || figure.precision() - figure.scale() > 10) {
252	            throw new PlanRefusedException("The amount must be 0.00 or more, with up to two decimals");
253	        }
254	        return figure.setScale(2);
255	    }
256	
257	    private static int everyOf(String every) {
258	        String typed = every == null ? "" : every.trim();
259	        if (!typed.matches("\\d{1,6}") || Integer.parseInt(typed) < 1) {
260	            throw new PlanRefusedException("A plan runs every whole number of days, at least 1");
261	        }
262	        return Integer.parseInt(typed);
263	    }
264	
265	    private static int dayOf(String day) {
266	        String typed = day.trim();
267	        if (!typed.matches("\\d{1,2}") || Integer.parseInt(typed) < 1 || Integer.parseInt(typed) > 31) {
268	            throw new PlanRefusedException("A monthly plan runs on a day of the month, 1 to 31");
269	        }
270	        return Integer.parseInt(typed);
271	    }
272	}

