1192	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by
1193	     *  plus its grace, see overdueFrom, is before the sheet's today) or a correction, else the late percent of
1194	     *  the figure for every 30-day boundary it is overdue past (its due-by plus its grace plus 30, 60, 90 ...
1195	     *  days), compounding: the late percent in force on that boundary date of the figure plus the charges
1196	     *  of the boundaries before it, rounded to two decimals as the claim's date decides (see roundingOf), the
1197	     *  charges added up. It follows the sheet's today until a statement binds the
1198	     *  claim's due, charge included. A waived claim bears none. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
1199	     *  claim as if it were still OPEN. */
1200	    private BigDecimal lateChargeOf(String sheetId, Person person, Claim claim, BigDecimal figure, boolean open,
1201	            LocalDate asOf) {
1202	        BigDecimal none = BigDecimal.ZERO.setScale(2);
1203	        if (!open || claim.isCorrection() || claim.isWaived()) {
1204	            return none;
1205	        }
1206	        LocalDate from = overdueFrom(sheetId, person, claim, asOf);
1207	        long days = ChronoUnit.DAYS.between(from, todayOr(sheetId, asOf));
1208	        if (days < 30) {
1209	            return none;
1210	        }
1211	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
1212	        BigDecimal charge = none;
1213	        for (long boundary = 1; boundary <= days / 30; boundary++) {
1214	            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * boundary), asOf);
1215	            if (pct.signum() != 0) {
1216	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
1217	            }
1218	        }
1219	        return charge;
1220	    }
