590	     *  not bound by a statement (a bound claim stays in whatever its date). A hold does not take it out:
591	     *  a hold only bears on the pools' cuts. */
592	    public boolean countsLive(LocalDate retiredFrom, LocalDate today) {
593	        return counts() && !deferredOn(today) && (stated || !retiredOn(retiredFrom, today));
