900:     private Claim move(String sheetId, String user, Long personId, Long id, Long toPersonId, boolean samePerson) {
901:         Person from = person(sheetId, personId);
902:         Person to = person(sheetId, toPersonId);
903:         // Lock the sheet first, as opening does: a numbered claim takes the next number.
904:         sheets.lock(sheetId);
905:         Claim claim = claim(sheetId, personId, id);
906:         if (!settings.allows(sheetId, user, Permission.REASSIGN)) {
907:             throw new ReassignRefusedException(user);
908:         }
909:         if (!claim.getStatus().canReassign()) {
910:             throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
911:         }
912:         if (!samePerson && from.getId().equals(to.getId())) {
913:             throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
914:         }
915:         if (claim.isCorrection()) {
916:             throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
917:         }
918:         refuseClosed(sheetId, claim.getDueBy());
919:         refuseRetired(to, claim.getDate());
920:         claim.setPersonId(to.getId());
921:         if (claim.getNumber() != null) {
922:             String old = claim.getNumber();
923:             claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
924:             claims.retireNumber(sheetId, old);
925:         }
926:         claim.unbind();
927:         claims.saveAndFlush(claim);
928:         claims.relist(claim.getId());
929:         Claim saved = claim(sheetId, to.getId(), id);
930:         audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
931:                 + " from=" + from.getName() + " to=" + to.getName());
932:         return saved;
933:     }
