16	/**
17	 * A viewer sees every screen and figure and can change nothing: every request that would change a
18	 * sheet is refused (403) before it reaches its controller, so it writes nothing to the store or the
19	 * audit. Loading a sheet changes nothing and is let through; so are the bulk actions, which a
20	 * viewer takes with nothing done (every selected item refused, see the bulk services), and the
21	 * plans' generate and the periods' monthly generate, which make nothing for a viewer (see the plan
22	 * and period services).
23	 */
24	@Component
25	public class ViewerGuard implements HandlerInterceptor {
26	
27	    /** The sheet-scoped requests the guard watches. */
28	    public static final String PATTERN = "/api/sheets/{sheetId}/**";
29	
30	    /** The requests a viewer may make: loading a sheet, the bulk actions that refuse every item, and
31	     *  generating plans' claims or monthly periods, which makes none for a viewer. */
32	    private static final Set<String> LET_THROUGH = Set.of(
33	            "/api/sheets/{sheetId}/load",
34	            "/api/sheets/{sheetId}/claims/open",
35	            "/api/sheets/{sheetId}/claims/settle",
36	            "/api/sheets/{sheetId}/claims/void",
37	            "/api/sheets/{sheetId}/claims/reassign",
38	            "/api/sheets/{sheetId}/people/grade",
39	            "/api/sheets/{sheetId}/people/retire",
40	            "/api/sheets/{sheetId}/people/hold",
41	            "/api/sheets/{sheetId}/plans/generate",
42	            "/api/sheets/{sheetId}/periods/generate");
43	
44	    private final AntPathMatcher paths = new AntPathMatcher();
45	    private final SettingService settings;
46	
47	    public ViewerGuard(SettingService settings) {
48	        this.settings = settings;
49	    }
50	
51	    @Override
52	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
53	        String method = request.getMethod();
54	        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
55	            return true;
56	        }
57	        String path = request.getRequestURI().substring(request.getContextPath().length());
58	        if (!paths.match(PATTERN, path) || LET_THROUGH.stream().anyMatch(p -> paths.match(p, path))) {
59	            return true;
60	        }
61	        String header = request.getHeader(SignedInUser.HEADER);
62	        if (header == null || header.isBlank()) {
63	            return true;
64	        }
65	        Map<String, String> vars = paths.extractUriTemplateVariables(PATTERN, path);
66	        String sheetId = URLDecoder.decode(vars.get("sheetId"), StandardCharsets.UTF_8).trim();
67	        if (settings.isViewer(sheetId, SignedInUser.decode(header))) {
68	            response.setStatus(HttpStatus.FORBIDDEN.value());
69	            return false;
70	        }
71	        return true;
72	    }
73	}

